// index.js — ربات فال تاروت فارسی 🔮
//
// بازسازی سفر مشتریِ یک تاروت‌خوان حرفه‌ای در تلگرام (۵ مرحله):
//  ۱) پیش‌جلسه: پرسشنامه‌ی تمرکز + سؤال کاربر (متن/ویس)
//  ۲) فضاسازی: مدیریت انتظارات + تمرین تنفس
//  ۳) خوانش: بُر زدن با توقفِ کاربر → انتخاب ۳ کارت از گرید ۲۴تایی →
//     پی‌وال دقیقاً قبل از افشا (اوج کنجکاوی) → افشای مرحله‌ای با spoiler →
//     حلقه‌ی بازخورد وسط خوانش (پاسخ منفی = فراخوانی کوچک تصحیح)
//  ۴) پایان‌بندی: روایت پیوندی + سه قدم عملی + جمله‌ی توانمندساز
//  ۵) قلاب بازگشت: مدیاگروپ یادگاری + milestone ۱۴روزه + کد تخفیف اولین خرید + رفرال
//
// مغز فالگیر: google/gemini-2.5-flash (OpenRouter) — تک‌فراخوانی per فال، پیش‌فراخوانی بعد از انتخاب کارت سوم.
// چندزبانه: همه‌ی متن‌ها/پرامپت‌ها از locales/<LOCALE>.js؛ هر زبان بعداً یک اپ pm2 جدا با ENV_FILE خودش.
// ⚠️ **اولین import و باید اول بماند.** `.env` را بار می‌کند تا ماژول‌هایی که سرِ
// بارگذاری از `process.env` می‌خوانند (`LOCALE` در `reading-core.js` و `ganjineh.js`)
// مقدارِ درست را ببینند. در ESM importهای ایستا قبل از بدنه اجرا می‌شوند، پس
// صداکردنِ `dotenv.config()` در همین فایل **دیر** بود. شرح کامل در خودِ آن ماژول.
import './env-boot.js';
import { mkdirSync, existsSync } from 'fs';
import { createHash, randomInt } from 'crypto';
import { Telegraf, Markup } from 'telegraf';
import Database from 'better-sqlite3';
import CARDS, { CARD_BY_KEY } from './cards.js';
import SPREADS, {
  DAILY, SPREAD_BY_ID, SPREADS_V3, spreadsFor, faOf,
  TOPICS_V3, TOPIC_BY_KEY, SIZES_V3, spreadIdOf, topicOf, topicForAnalytics,
} from './spreads.js';
import { log, logErr } from '../../shared/logger.js';
import { registerGlobalErrorHandlers } from '../../shared/errors.js';
import { EVENTS, ensureAnalytics, track, trackOnce, captureStart } from '../../shared/analytics.js';
import {
  ensureAb, variant, peekVariant, expose,
  reserveStratifiedVariant, exposeStratifiedVariant, releaseStratifiedReservation,
} from '../../shared/ab.js';
// پشتیبانی مشترکِ همه‌ی ربات‌ها (حساب + کدِ پیگیری + لینکِ پیامِ آماده) — متن‌ها از locale می‌آیند
import { registerSupport, supportRow, supportReply, supportLink } from '../../shared/support.js';

/* کدِ پیگیریِ پشتیبانیِ این ربات (بند ۶ج ریشه). تک‌منبع شد چون از ۱۴۰۵/۰۶/۲۲ دو
 * مصرف‌کننده دارد: `registerSupport` و دکمه‌ی CTAی پرچمِ `needs_support`. دو رشته‌ی
 * `'TRT'` در دو جا یعنی دیر یا زود یکی عوض می‌شود و کدِ تیکت‌ها بی‌صدا دو تکه می‌شود. */
const SUPPORT_BOT_CODE = 'TRT';
import { loadingFrame, pace, LOADERS, ACTIVE } from './loading.js';
// ثبتِ خودکارِ مسیرِ ریزِ کاربر (view/act) — قیفِ ریزِ داشبورد از همین تغذیه می‌شود
import { registerJourney, logPush } from '../../shared/journey.js';
import { startHeartbeat } from '../../shared/heartbeat.js';
import { analyzeReceipt, decideReceipt } from './cardpay.js';
import { scoreSpreads, RECO } from './reco.js';
import { normalizeVerdict, decisiveMode, headlineOk, evasionIn } from './verdict.js';
import { repairDefects } from './repair.js';
import { configureLocale } from './locale-boot.js';
import { installSerialDispatch } from './dispatch.js';
import { eligibleCards, pickVariant, textOf as ganjinehText, countOf as ganjinehCount, NO_REPEAT_DRAWS } from './ganjineh.js';
// هسته‌ی خالصِ خوانش: کلاینتِ OpenRouter، موتورِ دک، کانتکست و رندرِ متنِ نهایی.
// همان کد را `tools/reading-lab.mjs` هم صدا می‌زند تا تستِ آفلاین دقیقاً همان چیزی را
// اجرا کند که کاربر می‌بیند (کپی نداریم، پس drift ممکن نیست).
import {
  FLASH, READING_MODEL, FALLBACK_MODEL, OR_TIMEOUT_MS,
  orChatResilient, orTranscribe, parseJsonLoose, setUsageSink,
  seedToInt, mulberry32, shuffledDeck, drawCards, botToday, botDaysAgo, botHour, GRID_SIZE,
  checkV4Shape, softMissesV4, v4Text,
  buildReadingCtx, renderV4, cardName, positionName, choiceLabelsFor, spreadName, cardKeywords,
  CHAT_PLAN, CHAT_MODEL,
} from './reading-core.js';
// 🗣 هسته‌ی خالصِ گفتگو — دوقلوی reading-core برای فیچرِ چت. همان کد را
// `tools/chat-lab.mjs` صدا می‌زند، پس سنجه‌ی آزمایشگاه دقیقاً همان متنی را می‌بیند
// که به کاربر می‌رسد (گارد و سنجه یک کد، درسِ ثبت‌شده‌ی گافِ تیزر).
import {
  buildChatCtx, packHistory, toMessages, crisisIn, smallTalkIn, hookOk,
  cleanChatReply, chatOutOk, parseChatOut, questionWordsOf, configureChatLang,
} from './chat-core.js';

/* ===== 1) ENV و ثابت‌ها ===== */
const BOT_TOKEN          = process.env.BOT_TOKEN?.trim();
const OPENROUTER_API_KEY = process.env.OPENROUTER_API_KEY?.trim();
if (!BOT_TOKEN)          { logErr('❌ BOT_TOKEN خالی است');          process.exit(1); }
if (!OPENROUTER_API_KEY) { logErr('❌ OPENROUTER_API_KEY خالی است'); process.exit(1); }

import { STARS_EXPERIMENT, ladderFor, starsFor, buildInvoice, registerStarsPay, refundStars } from './starspay.js';

const LOCALE = process.env.LOCALE?.trim() || 'fa';
const L = (await import(`./locales/${LOCALE}.js`)).default;
/* 💳 ریلِ پرداخت per زبان (بند ۲و ریشه). فارسی کارت‌به‌کارت می‌ماند و بقیه استارز،
 * چون تلگرام فروشِ کالای دیجیتال در بات را روی موبایل اجباراً به استارز محدود کرده.
 * این تنها واگراییِ ساختاریِ مجاز بینِ زبان‌هاست؛ بقیه‌ی UI و UX یکی می‌ماند.
 * رول‌بکِ یک‌خطی: `starsRail = false` → رفتار دقیقاً مثلِ قبل برای همه‌ی زبان‌ها. */
const PAY_RAIL = LOCALE === 'fa' ? 'card' : 'stars';
const starsRail = PAY_RAIL === 'stars';
/* برچسبِ ماهِ تولد از خودِ locale می‌آید، نه از ganjineh.js. ایندکس ۱..۱۲ بینِ همه‌ی
 * زبان‌ها یکی است (روی `users.birth_month` کاربرانِ واقعی نشسته)، ولی **برچسبش**
 * زبانی است: فارسی ماهِ شمسی می‌گوید و زبانی که تقویمِ دیگری دارد می‌تواند همان
 * ایندکس را با نامِ برجِ متناظر نشان بدهد، بدونِ اینکه دیتای گنجینه جابه‌جا شود. */
const monthLabel = (m) => L.buttons.birthMonths[Number(m) - 1] || '';

/* ⚖️ دادهٔ زبانیِ حکمِ قاطع و جداکننده‌ی خط‌تیره را از همین locale به دو ماژولِ خالص
 * تزریق می‌کند. **قبل از هر خوانشی** و یک‌بار موقعِ boot اجرا می‌شود.
 * بدونِ این، رباتِ غیرفارسی خرابیِ بی‌صدا می‌گرفت: `normalizeVerdict` برای جوابِ
 * روسی null می‌داد و بلوکِ جواب بی‌هیچ خطایی از خوانش حذف می‌شد (بند ۱۰). */
/* 🌍 تک‌نقطه‌ی پیکربندیِ زبان: حکمِ قاطع، جداکننده‌ی «—»، و نامِ کارت/جایگاه/چیدمان.
 * آزمایشگاه هم **همین** تابع را صدا می‌زند تا آن‌چه سنجیده می‌شود با آن‌چه کاربر
 * می‌بیند یکی بماند. برای `fa` هیچ‌کدام از این جدول‌ها در locale نیستند، پس هسته به
 * همان فیلدهای هاردکدِ `cards.js`/`spreads.js` fallback می‌کند و فارسی دست‌نخورده است. */
configureLocale(L);
const fmt = L.fmt;
// فال حافظ: دیتای استاتیکِ **per زبان** (امروز فقط `hafez.fa.js`). زبانی که فایلِ خودش را
// ندارد آرایه‌ی خالی می‌گیرد و فیچر خودکار خاموش می‌شود (`if (HAFEZ.length)` سرِ هر مسیر).
// ⚠️ نامِ فایل حتماً `${LOCALE}` داشته باشد: قبلاً `./hafez.js` بی‌قید import می‌شد و
// کامنتش ادعا می‌کرد «زبان‌های دیگر بدون فایل»، در حالی که هر زبانی همان غزل‌های فارسی را
// می‌گرفت. چون `FREE_MENU_ENABLED` خاموش بود کسی ندیدش؛ تله‌ی خفته بود، نه باگِ زنده.
const HAFEZ = await import(`./hafez.${LOCALE}.js`).then(m => m.default.ghazals).catch(() => []);
// کوییز «کدام کارتِ تاروتی؟»: متنِ شخصیتی per کارتِ آرکانای بزرگ (سؤال‌ها/امتیازدهی در locale).
// این هم **پروزِ فارسی** است نه منطق، پس مثل حافظ per زبان است.
const QUIZ = await import(`./quiz.${LOCALE}.js`).then(m => m.default.personalities).catch(() => ({}));
// 📚 جدولِ دانشِ کارت (فارسی، تولیدِ آفلاین از منبعِ آموزشی — tools/build-card-knowledge.mjs).
// **RAG نیست و لازم هم نیست:** کلیدِ بازیابی قطعی است (می‌دانیم کدام کارت کشیده شده)، پس یک
// lookup کافی است — بدونِ embedding، بدونِ شبکه، زیر یک میلی‌ثانیه.
// فقط ردیفِ همان کارت‌هایی که کشیده شده‌اند به پرامپت می‌رود، نه کلِ جدول.
// fail-safe: اگر فایل نباشد یا خراب باشد، خوانش دقیقاً مثل قبل کار می‌کند.

const MAX_VOICE_SEC  = 120;              // سقف طول ویسِ سؤال (خودِ فایل به مدل می‌رود، پس سقف = سقفِ توکنِ ورودی)
const MAX_VOICE_BYTES = 3 * 1024 * 1024;

// ⚠️ TEST_PHASE: تا وقتی true است دکمه‌ی «ریست ربات (تست)» برای همه فعال است.
// false = ربات زنده (لانچ ۱۴۰۵/۰۴/۲۰): دکمه کلاً مخفی؛ /reset فقط برای OWNER می‌ماند.
const TEST_PHASE = false;

// نسخه‌ی محصول (کوهورت users.first_version): با هر تغییر «رفتاری» رو-به-کاربر bump کن — بند «قوانین ربات زنده» CLAUDE.md ریشه
// 1.1.0: رسیدِ پرداخت از ایجنتِ کارت‌به‌کارت (auto-approve + برگشت/بی‌اعتمادی) رد می‌شود.
// 1.1.1: فلوی رسید انسانی‌تر شد (پیامِ «فرستاده شد» + تأخیرِ ۳ تا ۱۰ ثانیه، بدونِ لوکنندنِ ایجنت)
//        + گاردِ قطعیِ مبلغِ بیشتر (پرداختِ اضافه → تأیید، نه رد) + تضمینِ اطلاع‌رسانیِ رد به کاربر.
// 1.1.2: فقط دو پیامِ نهاییِ رسید (تأیید/رد یکپارچه با پشتیبانی @Efficient_Support، بدونِ «رسید نیست»/دلیل)
//        + دکمه‌ی «کپی شماره کارت» (copy_text) زیرِ فاکتورهای کارت‌به‌کارت.
// 1.3.0: ناوبری درختی + گاردِ فلوی بازِ پرداخت (قرارداد State Management یکپارچه) — پشتِ NAV_GUARD_ENABLED.
// 1.3.1: پالایشِ کپیِ آنبوردینگ/خوانش — دکمه‌ی سوم «همه فال‌ها»، کارت روز در کاتالوگ،
//        آشکارسازیِ کیبورد بعد از «یه قرار کوچیک»، انتقال جمله‌ی فضای امن به قبلِ نوشتنِ سؤال.
// 1.4.0: استیت‌های ورودی (askQuestion/askTopic) دیگر دکمه ندارند (تمرکز روی نوشتن) + گاردِ «فالِ باز»
//        (blockDuringOpenReading) با دو دکمه‌ی «ادامه/انصراف» — قرارداد State Management بند ۹ب.
// 1.5.0: دکمه‌ی «💬 پشتیبانی» در منوی اصلی (مشترکِ همه‌ی ربات‌ها) — لینکِ چتِ پشتیبانی با
//        پیامِ آماده‌ی حاویِ کدِ پیگیریِ #TRT-<user_id> (shared/support.js).
// 1.6.0: بازطراحیِ پی‌والِ کم‌موجودی (بزرگ‌ترین نقطه‌ی ریزش): پیامِ کوتاهِ شخصی‌شده با تعدادِ
//        کارت و قیمت، تخفیف از پیام حذف و پشتِ دکمه‌ی «تخفیف می‌خوام» رفت، تخفیفِ اولین شارژ
//        ۳۵٪→۵۰٪ و دیگر خودکار نیست (کدِ شخصیِ کپی‌شدنی)، و برای کاربرِ شارژکرده مسیر دعوت دوستان.
// 1.6.1: سه فیکسِ ریلِ پرداخت (از تحلیلِ جرنیِ یک کاربرِ واقعی): کدِ تخفیفِ اشتباه دیگر کاربر را
//        از مرحله‌ی کد بیرون نمی‌اندازد، متنی که خودش یک کدِ تخفیف است دیگر «رسید» حساب نمی‌شود،
//        و شروعِ فالِ جدید وقتی فالِ رزروشده منتظرِ پرداخت است دیگر آن را بی‌صدا یتیم نمی‌کند.
// 1.6.2: کدِ تخفیفِ اولین شارژ دیگر با یک فاکتورِ رهاشده برای همیشه قفل نمی‌شود (فاکتورِ
//        pending بدونِ رسید عملاً غیرقابل‌دسترس است و نباید کد را نگه دارد)، پیامِ «قبلاً
//        استفاده شده» از «نامعتبر» جدا شد، و پیشنهادِ کد با پذیرشِ کد هم‌شرط شد.
// 1.7.0: دکمه‌ی «🎁 تخفیف می‌خوام» در پی‌وال فقط برای کسی که واقعاً تخفیفِ اولین شارژ
//        دارد نشان داده می‌شود، و مسیرِ «دعوت دوستان به‌جای تخفیف» حذف شد (وسطِ فالِ
//        رزروشده کاربر را از خریدش منحرف می‌کرد). تک‌منبعِ شرط: firstDiscountAvailable().
// 2.0.0: بازطراحیِ کاملِ ورود و ریلِ اولین پرداخت — هدیه‌ی خوش‌آمدِ ۳۰k (آنبوردینگ دو پیامی:
//        اول ارزش، بعد اسم)، اولین فالِ سه‌کارتی بدونِ پی‌وال، دکمه‌ی «پرداختِ هزینه‌ی همین فال»
//        به‌جای مرحله‌ی «چقدر شارژ کنم؟»، تخفیفِ اولین پرداخت ۵۰٪→۲۰٪ و فقط روی همان فال
//        (بدونِ کد و بدونِ سقف)، نردبانِ شارژ ۵۰/۱۰۰/۲۰۰k با هدیه فقط از ۲۰۰k، و حذفِ پوشِ
//        دوهفته‌ای به نفعِ تنها قلاب بازگشت: یادآوریِ شبانه‌ی کارت روز با انصرافِ دومرحله‌ای.
// 2.1.0: پیشنهاددهنده‌ی امتیازی جای پیشنهادِ هاردکد را گرفت (کارتِ روز دیگر همان فالی را
//        که کاربر تازه گرفته پیشنهاد نمی‌دهد) + کیبوردِ منو دیگر گم نمی‌شود.
// 2.2.0: صفِ اقدامِ پشتیبانی (تأییدِ دستیِ پرداختِ ردشده، شارژ/کسرِ دستی، بازکردنِ فال) +
//        حداقلِ مبلغ شارژ، بعد از باگی که یک «۸» یک کدِ ۱۰۰٬۰۰۰ تومانی را سوزاند.
// 2.3.0: پرداختِ کمتر از فاکتور دیگر رد نمی‌شود؛ فاکتور به مبلغِ واقعاً پرداخت‌شده اصلاح
//        می‌شود، کاربر دقیقاً همان‌قدر اعتبار می‌گیرد و دلیلِ اصلاح لاگ می‌شود.
// 2.4.0: فال‌های تصمیم‌محور (آری یا نه، دوراهی) با یک «جوابِ قاطع + نشونه» تمام می‌شوند،
//        از فیدبکِ کاربرِ واقعی که گفت جوابِ روشنی که دنبالش بود را نگرفت.
// 2.5.0: کاربری که اعتبارش کافی است دیگر صفحه‌ی قیمت‌دار نمی‌بیند؛ صریح می‌گوید پرداختی
//        لازم نیست. از تحلیل جرنی: کاربرانی با موجودیِ دقیقاً کافی یک تپ تا فالشان مانده
//        بودند و حرکت نمی‌کردند، یعنی مانع پول نبود، صفحه شبیه پی‌وال بود.
// 2.7.0: گیتِ عضویت در کانال برای کاربرِ جدید (معرفی → دعوت به عضویت → هدیه لحظه‌ی تأیید)
//        + «عشق و رابطه» محبوب‌ترین و اولِ کاتالوگ شد، سه‌کارتی و ۳۰٬۰۰۰ تومان یعنی دقیقاً
//        هم‌اندازه‌ی هدیه‌ی خوش‌آمد، تا کاربرِ تازه پرتقاضاترین فال را با اعتبارِ هدیه بگیرد.
// 2.7.1: حذفِ تکرارِ معرفی بعد از گرفتنِ نام (کاربر یک متن را دو بار می‌دید) و جایگزینی‌اش
//        با فکتِ واقعیِ «۸۶٪ گفتن خوانششون با واقعیت خوند» + پررنگ‌کردنِ «هوش مصنوعی» در معرفی.
// 2.7.2: سه فیکس از تستِ دستیِ مالک — یادآوریِ گیت روی آپدیتِ سرویسیِ my_chat_member
//        فرستاده می‌شد، ریستِ ادمین وسطِ گیت بلاک می‌شد، و payloadِ اتریبیوشن از کلمه‌ی
//        دومِ هر متنی خوانده می‌شد (ریستِ ادمین `payload:"ریست"` ثبت می‌کرد). + کپیِ فکت.
// 2.7.3: بازنویسیِ پیامِ اول (بدونِ توضیحِ مکانیک؛ «همون تجربه‌ی تاروت‌خوانِ حرفه‌ای، فقط
//        توی جیبت») + آزمایشِ A/B روی همان پیام: control با بندِ «قدرتش رو از هوش مصنوعی
//        می‌گیره» و no_ai بدونِ آن. تک‌متغیره، تا نتیجه تفسیرپذیر بماند.
// 2.8.0: موضع‌گیریِ «هوش مصنوعی» از فلو برداشته شد (بیرون از ربات، روی بنر تبلیغاتی تست
//        می‌شود) و آزمایشِ gate_intro_ai متوقف شد. به‌جایش آزمایشِ intro_order: همان دو
//        بلوکِ آنبوردینگ، فقط ترتیبشان عوض می‌شود (تجربه اول یا آمار اول).
// 2.9.0: کاتالوگ با هدیه هم‌تراز شد — همه‌ی فال‌های موضوعیِ ۵کارتی/۵۰k به ۳کارتی/۳۰k
//        رفتند (قانونِ ۱۰k per کارت دست‌نخورده؛ قیمت با کم‌کردنِ کارت پایین آمد، نه با
//        تخفیف). از تحلیلِ دور پنجم: فالِ گران‌تر از هدیه ۷٪ تحویل داشت و ارزان‌تر ۷۱٪.
// 2.9.1: اصلاحِ ابهامِ کپیِ «دو مورد اول» در پیشنهادِ فالِ بعدی ← «دو تا پیشنهاد اول»
//        (کاربرِ واقعی فکر کرده بود منظور دو تا کارتِ اوله).
// 3.0.0: دو تغییرِ بنیادین، هر دو **فعلاً فقط روی اکانتِ ادمین** (تصمیمِ صریحِ مالک: اول
//        خودش تست کند، بعد برای همه باز شود):
//        (۱) لحنِ خوانش: صریح، بی‌طفره، و پایانِ **هر** فال یک جوابِ مشخص + نشونه.
//        (۲) اقتصادِ سکه: واحدِ پولِ داخلی + سه بسته‌ی خرید + کاتالوگِ عشق‌محورِ تقابلی.
// 3.0.1: بازنویسیِ صدا از روی خوانش‌های واقعیِ یک تاروت‌خوانِ انسان (bots/tarot/STYLE.md):
//        فارسیِ گفتاری، حذفِ برچسبِ «نشونه‌ات» و شعارِ پایانی، و تصحیحِ مهم‌ترین اشتباهِ
//        نسخه‌ی قبل — زبانِ احتمال ممنوع نیست، جوابِ بی‌جهت ممنوع است.
// 3.1.0: تمرکز فقط روی کیفیتِ خروجی (تصمیمِ مالک). اقتصادِ سکه و کاتالوگِ نسل دوم **پارک**
//        شدند (پرچم خاموش، کد سرِ جایش) و آزمایشِ نامِ واحد منحل شد. پرامپت فشرده شد چون
//        ورودیِ متورم روی Flash هم گران است هم کیفیت را پایین می‌آورد. جمله‌های دلداریِ
//        پراکنده‌ی وسطِ جرنی هم در لحنِ جدید حذف شدند.
// 3.2.0: «سه قدم عملی» از پایانِ خوانش حذف شد (لحنِ کوچینگ می‌ساخت) و جدولِ دانشِ
//        کارت به فارسی **دستی** نوشته شد — کلیدِ OpenRouter فقط برای خودِ محصول است.
// 3.3.0: 🎯 لحنِ جدید برای **همه‌ی کاربران** باز شد (تا اینجا فقط ادمین بود). مالک لحن را
//        دستی تست و تأیید کرد. از این تاریخ هر کاربر این‌ها را می‌گیرد: پرامپتِ v2 (صدای
//        تاروت‌خوانِ انسان، حداکثر یک ایموجی، زبانِ احتمالِ جهت‌دار)، جوابِ قاطع در پایانِ
//        **هر** فال با دلیلِ لنگرخورده به نامِ کارت‌ها، جدولِ دانشِ ۷۸ کارت در پرامپت،
//        حذفِ سه قدمِ عملی و شعارِ پایانی و جمله‌های دلداریِ وسطِ جرنی، و پرسشِ «سؤالت چیه»
//        به‌جای «موضوعت چیه». هدفِ سنجش: **ریتنشن** (بازگشت و فالِ دوم) و کیفیتِ فیدبک.
// 3.4.0: 💸 قاعده‌ی هزینه: هیچ فراخوانیِ پولی قبل از کسرِ اعتبار. دو نشتی بسته شد
//        (رونویسیِ ویس لحظه‌ی ارسال، و پیش‌فراخوانیِ خوانش قبل از پی‌وال). ضمناً سؤالِ
//        صوتی حالا **یک** فراخوانی است: خودِ فایل کنارِ پرامپت به مدل می‌رود.
// 3.5.0: 🔮 بازطراحیِ ساختارِ خوانش (v4، فقط ادمین) از روی تحلیلِ خوانش‌های واقعیِ
//        انسانی + دو تحقیقِ مستقل: افشا = تیزرِ کوتاه، متنِ نهایی با **جواب** شروع
//        می‌شود، و بازخورد به آخرِ کار رفت با مقیاسِ ۱ تا ۵ درباره‌ی **رضایت**.
// 3.5.1: از تستِ میدانیِ سه فال: نقشه‌ی راه قبل از انتظار، کپشنِ ترتیبی (جا افتاده بود)،
//        تیزرِ واقعیِ کارت (نام+تصویر+معنی)، ایموجیِ بخش‌بندی، و سه فیکسِ کیفی —
//        نشتِ جمله‌ی نمونه، لغزشِ «شما»، و نبودِ حافظه/پنجره‌ی زمانی.
// 3.5.2: از دورِ دومِ تست — شماره‌گذاریِ ترتیبیِ کارت‌ها، دکمه‌ی «حالا جوابم رو بگو»
//        زیرِ کارتِ آخر (جمع‌بندی دیگر خودکار نمی‌آید)، فشرده‌سازیِ چیدمانِ بزرگ، و دو
//        باگ: تکرارِ برچسب و نشتِ دومِ مثالِ پرامپت در فیلدِ callback.
// 3.5.3: انضباطِ ورودی و «هرچه کد می‌تواند تضمین کند، در پرامپت نیاید»: شماره‌گذاریِ
//        کارت‌ها قطعی و از کد (strip+prefix)، پاک‌کردنِ خط تیره در کد، و قفلِ CI روی
//        سقفِ بدترین‌حالتِ ورودیِ مدل.
// 3.5.4: دورِ سوم — ریشه‌ی باگِ «پارسال» (فالِ قبلی تاریخ نداشت) با داده حل شد،
//        خوانشِ کارت‌ها یک بلوکِ پیوسته شد (نه ایموجی per کارت)، سؤالِ بازخورد با
//        ادعای ۸۶٪ هم‌راستا شد، و دو تکنیکِ تحقیق ۲ به‌شکلِ لنگرخورده اضافه شدند.
// 3.22.0: دستورِ فقط-ادمینِ /reel — ساختِ ویدیوی ریلز از یک فالِ ناشناس. رفتارِ هیچ
//         کاربرِ واقعی‌ای عوض نمی‌شود، ولی طبق بند ۲ج/۴ فیچرِ فقط-ادمین هم نسخه می‌گیرد.
// 3.24.0: نگارشِ انبوهِ گنجینه تمام شد — ۹۳۶ متن (۱۲ ماه × ۷۸ کارت × ۱ نسخه)،
//         دیگر هیچ کاربری به پیامِ «گنجینه‌ی این ماه آماده نیست» نمی‌خورد.
// 3.33.0: نسخه‌ی دومِ گنجینه تمام شد — ۹۳۶ متنِ تازه اضافه شد (۱۲ ماه × ۷۸ کارت)،
//         یعنی الان ۱۸۷۲ متن در کل. کارتی که ظرفِ ۷ بارِ اخیر تکرار شد، به‌جای
//         عینِ متنِ قبلی، زاویه‌ی تازه‌ای می‌بیند (طبقِ برنامه‌ی تدریجیِ GANJINEH.md).
// 3.34.0: نسخه‌ی سومِ گنجینه تمام شد — ۹۳۶ متنِ تازه‌ی دیگر اضافه شد (۱۲ ماه × ۷۸ کارت)،
//         یعنی الان ۲۸۰۸ متن در کل، هر خانه دقیقاً ۳ نسخه. طبقِ برنامه‌ی تدریجیِ
//         GANJINEH.md همچنان نقشِ نسخه‌ها «پشتیبانِ تکرار» است، نه چرخشِ اصلی.
// 3.50.0: دورِ اولِ گنجینه برای ru/pt/es — هر زبان ۹۳۶ متن (۱۲ برج × ۷۸ کارت × ۱ نسخه)،
//         با همان دست‌فرمونِ فارسی (۱۲ ایجنتِ موازی، یک per برج). یعنی از این نسخه به بعد
//         «کارتِ روزِ رایگان» برای هر چهار زبان محتوا دارد؛ قبلاً فقط fa پر بود و بقیه با
//         `ganjineh.js` fail-safe خاموش می‌ماندند. نسخه‌ی دوم و سوم (طبقِ برنامه‌ی
//         GANJINEH.md) دورهای بعدی‌اند.
// 3.77.0: بسته‌ی «جاودان» یک تاجِ اضافه داشت (👑👑) — رفع شد، فقط یک 👑. رنگِ دکمه‌اش
//         هم به قرمزِ «افسانه‌ای» رفت (عمداً هم‌رنگ، Bot API رنگِ چهارمی ندارد).
// 3.79.0: 🔙 **رول‌بکِ افزایشِ قیمتِ v3.75.0** (تصمیمِ صریحِ مالک، بر پایه‌ی تحلیلِ
//         `analytics/tarot/reports/2026-09-11-revenue-drop-recheck.md`). سه بسته به
//         ۳۰k/۶۰k/۱۵۰k برگشتند و دو بسته‌ی «افسانه‌ای»/«جاودان» به‌همراهِ آزمایشِ
//         نمایششان بازنشسته شدند. کلیدهایشان زنده می‌مانند (ردیفِ پرداختِ باز +
//         دکمه‌ی کهنه، بند ۲ج/۵ و ۶).
// 3.82.0: 🌙 برنده‌ی آزمایشِ `night_reminder` (کارتِ شانس) دیفالت شد.
// 3.83.0: پاداشِ دعوت ۵ ⟵ ۳ الماس برای فارسی (پله‌ی سومِ `REFERRAL_3_LOCALES`)، با
//         حفظِ وعده‌ی هر دو نسلِ قبلی؛ به‌علاوه‌ی دو ستونِ افزایشیِ `llm_usage` برای
//         سنجشِ کشِ پرامپت. تنها تغییرِ رو-به-کاربر همان عددِ پاداش است.
// 3.84.0: 🗣 گفتگوی پس از فال (فعلاً فقط-ادمین و فقط فارسی): بعد از تحویلِ فال کاربر
//         می‌تواند درباره‌ی همان فال سؤال بپرسد، هر سؤال یک الماس. بامپ حتی با
//         فقط-ادمین بودن اجباری است (بند ۲ج/۴): رفتار برای بخشی از کاربران عوض شده.
// 3.85.0: 🔕 فیکسِ باگِ زنده — دکمه‌ی «🔔 فردا یادآوری کن» (زیرِ کارتِ شانس) از v3.82.0
//         بی‌صدا **هر دو** یادآوریِ شبانه را روشن می‌کرد، پس ساعتِ ۲۲ کارتِ شانس و
//         بلافاصله زنجیره‌ی کارتِ روز می‌رفت. حالا فقط کارتِ شانس را روشن می‌کند؛
//         «دیگه یادآوری نکن» مثل قبل هر دو را خاموش می‌کند. سوییچِ سخت، نه A/B،
//         چون فیکسِ باگ است (بند ۲ج/۴).
// 3.86.0: 🎲 کفِ دستِ **اولِ** کارتِ شانس ۲ ⟵ ۱ الماس (`LUCKY_FIRST_MIN`). پله‌ی اولِ
//         «حذف نه، کوچک‌کردن» از تحقیقِ کارتِ شانس: ۴۳٫۶٪ دست‌ها دستِ اولِ عمرند، پس
//         پریمیومِ همین کف ۳۱٪ کلِ هزینه‌ی فیچر بود. دستِ دوم به بعد دست‌نخورده.
// 3.87.0: 🗣 گفتگوی پس از فال، دو یافته‌ی آزمایشگاه: قفلِ لحنِ گفتاری و «اسمِ قلاب را
//         نبر» در پرامپت (اکوی برچسب ۱۱/۱۵ ⟵ ۰/۱۵، لحنِ کتابی ۷/۱۵ ⟵ ۰/۱۵)، و
//         پاراگراف‌بندیِ **قطعی** در کد نه در پرامپت (۵۳٪ ⟵ ۱۰۰٪ داخلِ هدفِ ۲ تا ۶
//         خط). هر سه واریانتی که صریح «خط جدا کن» می‌گفتند بدتر شدند، پس آن مداخله
//         کنار گذاشته شد. + فیکسِ باگِ خفته‌ی چسبیدنِ خطوط در حذفِ نامِ نشتی.
// 3.91.0: 💰 نتیجه‌ی فاز ۱ نردبانِ قیمت اعمال شد — کفِ بسته‌ی معمولی ۱۰💎/۳۰k ⟵
//         **۵💎/۱۵k**، برای همه‌ی کاربران (تصمیمِ صریحِ مالک، بعد از تأیید مجددِ
//         نتیجه‌ی معتبر). `price_ladder_p1` بلافاصله بعد از تأییدِ زنده‌بودنِ همین
//         دیپلوی از داشبورد `stopped` می‌شود (نه قبلش — ترتیبِ مقدسِ ثبت‌شده‌ی
//         همین فایل: اول کد، بعد بستنِ آزمایش). فاز ۲ (بازوی `cheap`) عمداً شروع
//         **نشد** — خواسته‌ی صریحِ مالک: فعلاً تستِ تازه‌ای روی قیمت نمی‌خواهد.
//         جزئیات: بخشِ «آزمایشِ نردبانِ قیمت» پایینِ همین فایل.
// 3.92.0: 🗣💎 باگِ گزارشِ زنده‌ی مالک: اولویتِ قدیمیِ «اولین فال + کارتِ شانسِ باز»
//         روی دکمه‌ی گفتگو هنوز سوار بود، پس ریستِ ادمین (که کلِ ردیفش را پاک
//         می‌کند) همیشه تبلیغِ کارتِ شانس را به‌جای گفتگو نشان می‌داد. گزینه‌ی ب
//         (تصمیمِ صریحِ مالک): گفتگو همیشه مقدم است؛ معرفیِ کارتِ شانس به یادآوریِ
//         ساعتِ ۲۲ شبِ اولِ کاربر منتقل شد (`dueFirstNightLucky`، مستقل از
//         daily_reminder_off/lucky_reminder_on و از آزمایشِ night_reminder).
// 3.93.0: 🔔🔧 دو تغییرِ صریحِ مالک. (۱) دکمه‌ی «فردا یادآوری کن» ته دستِ کارتِ شانس
//         کاملاً حذف شد: یادآوریِ شبانه از v3.82.0 بای‌دیفالت برای همه روشن است،
//         پس آن دکمه همیشه پیشنهادِ روشن‌کردنِ چیزی بود که از قبل روشن بود. تنها دو
//         راهِ خاموش‌کردن ماند: «دیگه یادآوری نکن» زیرِ خودِ یادآوریِ شبانه، یا صفحه‌ی
//         تنظیمات. هندلرِ `lremind:` فقط برای دکمه‌های کهنه‌ی کش‌شده زنده ماند
//         (بند ۲ج/۶). (۲) 🐛 باگِ زنده‌ی گزارشِ ادمین با اسکرین‌شات: `ensureKeyboard`
//         مهرِ `kb_shown_at`/`kb_rev` را **قبل از تأییدِ ارسال** می‌زد؛ لاگِ سرور پر
//         بود از `403 Forbidden: bot was blocked` و `ECONNRESET` دقیقاً روی همین
//         `sendMessage`. حالا شکستِ ارسال هر دو مهر را به مقدارِ دقیقِ قبلی
//         برمی‌گرداند، پس یک شکستِ گذرا دیگر تورِ ترمیمِ بند ۹ب-۳ را برای ۲۴ ساعت
//         کور نمی‌کند.
// 💰 v3.94.0: آزمایشِ نردبانِ قیمتِ تازه‌ی `price_ladder_p3` — بازوی `bulk` کنارِ
// control/floor/cheap نشست. فرضیه‌ی مالک: کاربر با اعدادِ **بزرگ‌ترِ** الماس در
// بسته‌های میانی/بالا بیشتر ترغیب به خرید می‌شود، نه فقط با تومانِ کمتر. کلیدِ تازه
// چون price_ladder_p2 (control در برابرِ cheap) هنوز شروع‌نشده و تصمیمِ ثبت‌شده‌ی
// آن جدا می‌ماند؛ این فرضیه‌ی کاملاً متفاوتی است، نه ادامه‌ی همان مسیر.
const PRODUCT_VERSION = '3.94.2';
// ⚙️ منوی تنظیماتِ کاربر (v3.38.0). `false` → دکمه از کیبورد محو و هیچ هندلری ثبت
// نمی‌شود؛ رفتار دقیقاً مثل قبل (بند ۲ج/۸).
const SETTINGS_ENABLED = true;

/* ⌨️ نسخه‌ی کیبوردِ ماندگار (v3.39.0) — بند ۹ب-۲ ریشه.
   مسئله: کیبوردِ reply روی **گوشیِ کاربر** ذخیره است و هیچ متدی در Bot API نمی‌تواند از
   سمتِ سرور تازه‌اش کند؛ تنها چیزی که عوضش می‌کند فرستادنِ یک ReplyKeyboardMarkup تازه
   است. نقاطِ صدورِ فعلی (/start، بازگشت به منو، تشکرِ بعد از نمره، انصراف) هیچ‌کدام
   تضمین نمی‌کنند کاربر **به‌زودی** به آن‌جا برسد، پس یک دکمه‌ی تازه می‌توانست هفته‌ها
   نادیده بماند. (لانچِ v3.25.0 همین را با `KB_V2_EPOCH` حل کرد، ولی آن یک‌باره بود.)

   ⚠️ هر تغییری در ردیف‌ها یا برچسب‌های `mainKeyboard` باید `KB_REV` را در **همان PR**
   یک واحد بالا ببرد. فراموش‌کردنش یعنی آپدیت به کاربرِ فعلی نمی‌رسد — و چون هیچ خطایی
   نمی‌دهد، بی‌صدا. برای همین اثرانگشتِ شکلِ کیبورد در چکِ CI کنارِ همین عدد پین شده
   (`tools/check-kb-rev.mjs`): ویرایشِ کیبورد بدونِ بامپ، CI را قرمز می‌کند. */
const KB_REV = 1;
// اثرانگشتِ شکلِ فعلیِ کیبورد. `tools/check-kb-rev.mjs` دوباره حسابش می‌کند و با این
// مقایسه می‌کند؛ ناهم‌خوانی یعنی کیبورد عوض شده و KB_REV بامپ نشده. عددِ تازه را خودِ
// همان چک در پیامِ خطا چاپ می‌کند.
const KB_SHAPE_FINGERPRINT = '2f4e434197b4';
const FOCUS_REASK_DAYS = 7; // حوزه‌ی تمرکز حداکثر هفته‌ای یک‌بار دوباره پرسیده می‌شود (نه هر فال)

// 🎁 منوی سرگرمی‌های رایگان (کارت روز + فال حافظ؛ قلاب بازگشت روزانه بدون LLM).
// فعلاً خاموش عرضه می‌شود (dark launch): merge روی ربات زنده هیچ تغییرِ رفتاری نمی‌دهد.
// روشن‌کردن = یک‌خط true + bump PRODUCT_VERSION به 1.1.0 در همان PR (تغییرِ رفتاری).
// Rollback فوری: دوباره false کن → دکمه‌ی کیبورد، منو و همه‌ی callbackها محو و رفتار دقیقاً مثل قبل.
const FREE_MENU_ENABLED = false;

// 🌀 فال با موضوع آزاد: به کاربر سیگنال می‌دهد می‌تواند درباره‌ی «هر موضوعی» فال بگیرد (نه فقط کاتالوگ ثابت).
// Rollback فوری: این را false کن → دکمه و کپی‌های موضوع آزاد کاملاً محو می‌شوند و رفتار دقیقاً مثل قبل می‌شود
// (فال‌های open3/open5 که قبلاً ثبت شده‌اند بی‌ضرر در DB می‌مانند؛ پایپ‌لاین افشا از SPREAD_BY_ID می‌خواند).
const OPEN_TOPIC_ENABLED = true;

// 🧭 ناوبری درختی + گاردِ فلوی باز (قرارداد State Management، CLAUDE.md ریشه): هر استیتِ میانیِ فلو دکمه‌ی
// «بازگشت به منو» می‌گیرد، و پرداختِ باز دکمه‌های منو را بلاک می‌کند (پیام «فاکتور باز داری» + انصراف)
// به‌جای یتیم‌کردنِ بی‌صدای فاکتور. Rollback فوری: false کن → دکمه‌های nav و گارد محو، رفتار دقیقاً مثل قبل
// (callbackِ nav:menu ثبت‌شده می‌ماند تا دکمه‌ی کش‌شده هم بی‌خطر باشد).
const NAV_GUARD_ENABLED = true;

/* ═══════════ 🗣 گفتگوی پس از فال (v3.84.0) ═══════════
 *
 * بعد از تحویلِ فال، کاربر می‌تواند درباره‌ی **همان فال** سؤال بپرسد. هر سؤال یک
 * الماس، با حافظه‌ی کاملِ فال و گفتگو، و لحنِ عیناً همان لحنِ خوانش.
 *
 * الگوی دو ثابتِ بند ۲ج-۲ ریشه: `CHAT_AFTER_READING` کلیدِ خاموشیِ کلِ فیچر است و
 * `_ADMIN_ONLY` فقط دامنه. باز کردن برای همه = یک خط، رول‌بک = یک خط، و این دو مسیر
 * عمداً از هم جدا هستند. **هیچ‌جا پرچمِ خام صدا زده نمی‌شود، فقط `chatOn`** — چکِ CI
 * تعدادِ استفاده‌ی خام را روی ۲ قفل کرده (تعریف + helper).
 *
 * ⚠️ `CHAT_LOCALES` گیتِ **ساختاری** نسخه‌ی اول است: مالک صریح گفت v1 فقط فارسی، چون
 * آزمایشگاه و تستِ دستی روی فارسی است. کلیدهای locale در هر چهار زبان هست (الزامِ
 * `check-locale-shape`) ولی برای ru/pt/es کدِ مرده‌اند تا دورِ آزمایشگاهِ خودشان
 * بیاید — همان الگوی ثبت‌شده‌ی `invoiceReminder`. ردیفِ جدولِ استثناهای زبانی دارد. */
const CHAT_AFTER_READING = true;
const CHAT_AFTER_READING_ADMIN_ONLY = true;
const CHAT_LOCALES = ['fa'];
const chatOn = (uid) => CHAT_AFTER_READING
  && CHAT_LOCALES.includes(LOCALE)
  && (!CHAT_AFTER_READING_ADMIN_ONLY || isTester(uid));

const CHAT_PRICE       = 1;    // الماس per سؤال (throttleِ اصلی؛ سقفِ نوبت فقط ضدِ حلقه است)
/* 🎁 سؤالِ **اولِ هر فال** رایگان است (خواسته‌ی صریحِ مالک: «انگار که رو هزینه‌ی فالش
 * بوده»). دو خاصیتِ عمدی: (۱) کاربرِ بی‌موجودی هم اولین سؤالش را می‌پرسد، یعنی هیچ‌کس
 * بدونِ چشیدنِ گفتگو به دیوار نمی‌خورد؛ (۲) شمارشِ «اولین» **داخلِ همان تراکنشِ کسر**
 * انجام می‌شود، وگرنه دو تپِ هم‌زمان دو سؤالِ رایگان می‌دادند.
 * ⚠️ مبنای شمارش «سؤالِ **ریفاندنشده**» است، نه «سؤالِ ثبت‌شده»: سؤالِ رایگانی که مدل
 * جوابش را نداد ریفاند می‌شود و **دوباره رایگان** می‌ماند؛ کاربر بابتِ خرابیِ ما
 * سهمیه‌ی مهمانی‌اش را از دست نمی‌دهد. رول‌بک: `false` ⟵ هر سؤال از اول ۱ الماس. */
const CHAT_FREE_FIRST  = true;
/* 🅿️ سؤالی که به پی‌وال خورد **گم نمی‌شود**: با نقشِ `pending` پارک می‌شود و لحظه‌ای که
 * موجودی از صفر در بیاید، ۱ الماس کم می‌شود و جواب با ریپلای به **همان سؤال** می‌رود.
 * ⚠️ فقط از دو راه: **خرید** و **کارتِ شانس**. پاداشِ دعوت عمداً بیرون است، چون آن‌جا
 * کاربر همان لحظه کاری نکرده (دوستش فال گرفته) و پیامِ خودکار بند ۹ب-۴ ریشه را نقض
 * می‌کرد. این دو تا استثنا نیستند: جوابِ سؤالِ خودِ کاربر، بعد از اقدامِ خودِ کاربر.
 * رول‌بک: `false` ⟵ سؤال پارک نمی‌شود و هیچ پیامِ خودکاری نمی‌رود. */
const CHAT_PENDING_RESUME = true;
const CHAT_WINDOW_DAYS = 0;    // ۰ = هر فالِ تحویل‌شده، بدونِ محدودیتِ زمانی (تصمیمِ مالک)
/* سقفِ **فرار**، نه throttle: ۳۰ سؤال یعنی ~$۰٫۰۲۴ هزینه در برابرِ ۳۰ الماس درآمد، پس
 * از نظرِ اقتصادی هیچ ریسکی ندارد. این عدد فقط جلوی یک حلقه‌ی باگ‌دار یا اسکریپت را
 * می‌گیرد. مالک صریح گفت سقفِ سخت نمی‌خواهد و خلاصه‌سازیِ کانتکست کارِ طول را می‌کند. */
const CHAT_MAX_TURNS   = 30;
const CHAT_VOICE       = false; // نسخه‌ی اول فقط متن (ویس = یک فراخوانیِ رونویسیِ اضافه per پیام)
/* 🚧 گاردِ استیتِ گفتگو (v3.88.0، خواسته‌ی صریحِ مالک — جانشینِ `CHAT_EXIT_GUARD` که
 * خاموش بود). تا v3.87.0 هر تپِ منو گفتگو را **بی‌صدا** می‌بست؛ حالا مثل هر فلوی
 * نیمه‌کاره‌ی دیگرِ این ربات (بند ۹ب/۲ ریشه) پیامِ صریحِ «ادامه می‌دم / بستن گفتگو»
 * می‌آید. تنها درِ بازِ دیگر **فلوی کسبِ الماس** است، و فقط وقتی موجودی صفر باشد —
 * چون تنها دلیلِ مشروعِ بیرون رفتن از گفتگو همان است که بتوانی ادامه‌اش بدهی.
 * رول‌بک: `false` ⟵ دقیقاً رفتارِ v3.87.0 (خروجِ بی‌صدا، بدونِ گارد). */
const CHAT_STATE_GUARD = true;
// 🏳️ فلگِ بازگشت: هر بار که استیتِ گفتگو بسته می‌شود، یک پیام با دکمه‌ی برگشت به همان
// گفتگو، ریپلای‌خورده به پایانِ فال. رول‌بک: `false` ⟵ فقط پیامِ همیشگی.
const CHAT_CLOSE_FLAG  = true;
const CHAT_ORPHAN_SEC  = 180;  // سنِ لازم برای ریفاندِ سؤالِ بی‌جواب (کوتاه‌تر = ریفاندِ کاربرِ منتظر)
const CHAT_NUDGE_TURN  = 12;   // نادجِ «تصمیم مالِ خودته»، یک بار در هر گفتگو
const CHAT_MAX_TOKENS  = 500;

// 🪙 UX v2.6 — نقطه‌ی کسرِ اعتبار از **پی‌والِ بعد از انتخابِ کارت‌ها** به **لحظه‌ی انتخابِ
// اندازه** منتقل شد (تصمیمِ صریحِ مالک). یعنی کاربر همان‌جا که «۵ کارتی (➖۵💎)» را می‌زند
// پول می‌دهد، و دیگر جلوتر هیچ پی‌والی نمی‌بیند.
// این پرچم **عمداً از UX_V2 جداست** تا رول‌بکش مستقل باشد: false → دقیقاً مسیرِ قبلی
// (insert در finishPicking + پی‌وال + کسر در unlock:) بدونِ اینکه بقیه‌ی UX v2 خاموش شود.
const PAY_AT_SIZE = true;
const payAtSizeFor = (uid) => PAY_AT_SIZE && uxV2For(uid);

/* 💎 انصرافِ کاربر بعد از کسر، پول را برنمی‌گرداند (تصمیمِ صریحِ مالک، ۱۴۰۵/۰۶/۱۲).
   «کاربر با دادنِ الماس ربات را استخدام کرده»: از همان لحظه محصول رزرو شده و از v3.53.0
   کارت‌ها کشیده و مدل هم اغلب هزینه‌اش را گرفته است. پس منصرف‌شدنِ **خودِ کاربر** دلیلِ
   برگرداندنِ پول نیست.
   ⚠️ ریفاند حذف نشد، فقط به جای درستش محدود شد: **خرابیِ خودمان** همچنان کامل برمی‌گردد —
   شکستِ کاملِ مدل بعد از همه‌ی فالبک‌ها (`startReveal`) و یتیمِ ری‌استارتِ وسطِ فراخوانی
   (`recoverOrphanReadings`). آن دو مسیر عمداً به این پرچم وصل **نیستند**.
   رول‌بکِ یک‌خطی: `true` → دقیقاً رفتارِ v3.53.0 (ریفاندِ لغو + جاروی ۲۴ساعته‌ی رهاشده). */
const REFUND_ON_CANCEL = false;

// 🧭 ثبتِ خودکارِ مسیرِ ریزِ کاربر (shared/journey.js): هر پیامِ خروجی (`view`) و هر اکشنِ ورودی
// (`act`) ثبت می‌شود تا در داشبورد بشود دید کاربر دقیقاً پشتِ کدام پیام/دکمه ریخته است.
// کاملاً fail-safe و بدونِ هیچ اثرِ رو-به-کاربر. Rollback فوری: false کن → هیچ رویدادِ ریزی
// ثبت نمی‌شود و هیچ متدی رپ نمی‌شود (رفتار دقیقاً مثل قبل؛ دیتای ثبت‌شده بی‌ضرر می‌ماند).
const JOURNEY_ENABLED = true;

// 🔑 عضویتِ اجباری در کانال برای کاربرِ **جدید** (v2.7.0): قبل از هدیه‌ی خوش‌آمد، کاربر یک
// پیامِ کوتاهِ معرفی می‌بیند و بعد دعوت به عضویت در کانال. هدیه دقیقاً لحظه‌ی تأییدِ عضویت
// واریز می‌شود، پس عضویت یک «هزینه» نیست، کلیدِ گرفتنِ هدیه است.
//
// دامنه‌ی گارد عمداً باریک است (بند ۲ج: کاربرِ زنده وسط فلو نباید بشکند): فقط کسی گیت
// می‌خورد که **هنوز هدیه‌ی خوش‌آمد نگرفته** باشد. هر کاربرِ فعلی، حتی نیمه‌آنبورد، از قبل
// هدیه را گرفته پس هرگز گیت نمی‌بیند و تجربه‌اش ذره‌ای عوض نمی‌شود.
//
// Rollback فوری: false کن → گیت و میدل‌ورش کاملاً محو، فلو دقیقاً مثل قبل (کاربرانی که
// gate را رد کرده‌اند بی‌ضرر می‌مانند؛ callbackِ gate:check ثبت می‌ماند تا دکمه‌ی کش‌شده خطا ندهد).
const JOIN_GATE_ENABLED = true;
/* 🌍 کانالِ گیت **per زبان**. تا قبل از این پیش‌فرض `@taroot_fa` هاردکد بود و
 * `write_env` برای زبان‌های تازه چیزی نمی‌نوشت، یعنی اولین چیزی که یک کاربرِ روس یا
 * برزیلی می‌دید «عضوِ این کانالِ فارسی شو» بود — و چون هدیه‌ی خوش‌آمد لحظه‌ی تأییدِ
 * عضویت واریز می‌شود، عملاً پشتِ یک کانالِ بی‌ربط قفل می‌شد.
 *
 * پیش‌فرضِ صادقانه برای زبانی که هنوز کانال ندارد **خاموش بودنِ گیت** است، نه
 * فرستادنش به کانالِ زبانِ دیگر. روزی که کانالِ آن زبان ساخته شد، یک ردیف این‌جا
 * (یا `GATE_CHANNEL` در `.env.<lang>`) گیتش را روشن می‌کند. */
const GATE_BY_LOCALE = {
  fa: { ch: '@taroot_fa', url: 'https://t.me/taroot_fa' },
  // ⚠️ نامِ کانالِ روسی و اسپانیایی دو «o» دارد و پرتغالی یک «o». عمدی است، نه تایپو:
  // یوزرنیمِ تک-oی آن دو در تلگرام گرفته شده بود. اشتباه‌نوشتنش یعنی گیت به کانالی
  // اشاره می‌کند که وجود ندارد، و چون چکِ عضویت fail-open است **بی‌صدا** بی‌اثر می‌شود.
  ru: { ch: '@TAROOT_RU', url: 'https://t.me/TAROOT_RU' },
  pt: { ch: '@TAROT_PT',  url: 'https://t.me/TAROT_PT'  },
  es: { ch: '@TAROOT_ES', url: 'https://t.me/TAROOT_ES' },
};
const GATE_CHANNEL     = process.env.GATE_CHANNEL?.trim()     || GATE_BY_LOCALE[LOCALE]?.ch  || '';
const GATE_CHANNEL_URL = process.env.GATE_CHANNEL_URL?.trim() || GATE_BY_LOCALE[LOCALE]?.url || '';
// هر دو لازم‌اند: کانالِ بدونِ لینک یعنی دکمه‌ی خرابِ «عضو شو» وسطِ اجباری‌ترین مسیرِ ربات.
const gateOn = () => JOIN_GATE_ENABLED && !!GATE_CHANNEL && !!GATE_CHANNEL_URL;
// وضعیت‌هایی که یعنی «عضو است». `restricted` فقط وقتی عضو است که is_member هم true باشد.
const GATE_OK_STATUS = new Set(['member', 'administrator', 'creator']);

// ⚖️ جوابِ قاطع برای فال‌های تصمیم‌محور (spreads.js → decisive؛ فعلاً آری/نه و دوراهی).
// از فیدبکِ کاربرِ واقعی: «اون جوابی که می‌خواستم رو آخر نفهمیدم و نگرفتم... اگه توش
// نشونه‌ای بتونه ببینه توی اون جوابه، می‌تونه خودشو آروم کنه.» منطقِ خالص: verdict.js
// Rollback فوری: false کن → پرامپت و پیامِ جواب کاملاً محو، خوانش دقیقاً مثل قبل
// (فال‌هایی که verdict شان در DB ذخیره شده بی‌ضرر می‌مانند و فقط نمایش داده نمی‌شوند).
const DECISIVE_VERDICT_ENABLED = true;

// 💳 صفحه‌ی «اعتبارت کافیه» به‌جای صفحه‌ی قیمت‌دار، برای کاربری که موجودی‌اش هزینه‌ی فال را
// پوشش می‌دهد. از تحلیل جرنی: چند کاربر با موجودیِ دقیقاً کافی در confirm_pay مانده بودند،
// یعنی مانع پول نبود؛ صفحه شبیه پی‌وال بود و نمی‌فهمیدند پرداختی لازم نیست.
// Rollback فوری: false کن → همان دکمه‌ی قیمت‌دار و متنِ قبلی برمی‌گردد، بدونِ هیچ اثر دیگری.
const COVERED_PAYWALL_ENABLED = true;

// 🎬 ویدیوی ریلز (فقط ادمین): دستورِ /reel یک ورک‌فلوی گیت‌هاب را صدا می‌زند که سوالِ بعدی
// را از Notion برمی‌دارد، یک فالِ **ناشناس** می‌گیرد (بدونِ نام و بدونِ حافظه) و خروجی را
// به‌جای متن، یک ویدیوی عمودیِ بی‌صدا می‌سازد و در همین چت می‌فرستد.
// خودِ ربات هیچ رندری نمی‌کند: نه Chrome می‌خواهد، نه CPU می‌گیرد، نه فلوی کاربرِ واقعی را
// لمس می‌کند. تنها کارش یک ریکوئستِ HTTP است.
// Rollback یک‌خطی: false کن → دستور کاملاً بی‌اثر می‌شود (کاربر عادی هم اصلاً نمی‌بیندش).
const VIDEO_REEL_ENABLED = true;
const VIDEO_DISPATCH_REPO = 'darkgreenblue/Telegram_bots';
// واریانت‌های مجازِ پس‌زمینه. allowlist عمدی است: آرگومانِ کاربر هرگز خام وارد payloadِ
// گیت‌هاب نمی‌شود، حتی وقتی فرستنده ادمین است.
const VIDEO_BACKGROUNDS = ['mystic', 'nature', 'minimal'];

// ادمین‌ها از env (کامای ADMIN_IDS که deploy از OWNER_TELEGRAM_ID می‌سازد) — مشترک با بقیه‌ی ربات‌ها
const ADMIN_IDS = (process.env.ADMIN_IDS || '100257975')
  .split(',').map(s => parseInt(s.trim(), 10)).filter(Number.isFinite);
const OWNER_ID  = ADMIN_IDS[0] || 100257975;
const isAdmin = (uid) => ADMIN_IDS.includes(uid);

// 🧪 **تستر** — کاربری که همه‌ی فیچرهای در-حالِ-تست (که فعلاً `_ADMIN_ONLY` اند) را می‌بیند
// و دکمه‌ی «ریست حساب» دارد، ولی **هیچ اختیارِ ادمینی ندارد**: نه تأیید/ردِ رسید، نه
// `/stats` و `/newcode`، نه هشدارهای مالی، نه هیچ دکمه‌ی ادمینِ دیگری.
//
// ⚠️ عمداً از `ADMIN_IDS` جداست و نباید با آن یکی شود: افزودنِ یک تستر به آن لیست،
// اختیارِ دست‌زدن به **پولِ کاربرانِ واقعی** را هم به او می‌داد (بند ۹ ریشه).
// افزودن/حذفِ تستر = ویرایشِ همین یک آرایه.
const TESTER_IDS = [
  5725984933,   // تسترِ دعوت‌شده‌ی مالک (۱۴۰۵/۰۵/۲۹)
];
// فیچرهای در-حالِ-تست از این می‌خوانند، نه از isAdmin — پس ادمین هم خودکار تستر است.
const isTester = (uid) => isAdmin(uid) || TESTER_IDS.includes(uid);

// ───────────────────────────────────────────────────────────────────────────
// 🎭 نسخه‌ی دومِ لحنِ خوانش (v3.0.0)
// ───────────────────────────────────────────────────────────────────────────
// چرا: ریتنشن پایین بود و فیدبکِ کاربرها و چند تاروت‌خوانِ حرفه‌ای یک حرفِ مشترک داشت —
// خوانش‌های ما محتاط، وسط‌باز و پر از «شاید» بودند و کاربر بدونِ جواب می‌رفت. نسخه‌ی دوم
// صریح می‌نویسد و **هر** فال (نه فقط فال‌های تصمیم‌محور) با یک جوابِ مشخص + نشونه تمام می‌شود.
//
// ✅ از v3.3.0 برای **همه‌ی کاربران** باز است. مسیرِ مرحله‌ای طبق بند ۲ج-۲ ریشه طی شد:
// از v3.0.0 تا v3.2.0 فقط اکانتِ ادمین آن را می‌دید، مالک دستی تست کرد و لحن را تأیید کرد
// (۱۴۰۵/۰۵/۲۵). Rollback فوری و بدونِ فکر: `READING_TONE_V2 = false` → پرامپت، رندرِ جواب،
// جمله‌های حذف‌شده و سه قدمِ عملی همه دقیقاً به حالتِ قبل برمی‌گردند.
// نکته: `_ADMIN_ONLY` عمداً حذف نشد تا اگر خواستیم دوباره فیچری را ادمین-محدود کنیم،
// مسیرِ باریک‌کردن هم یک‌خطی بماند (همان دو-پرچمِ بند ۲ج-۲).
const READING_TONE_V2 = true;
const READING_TONE_V2_ADMIN_ONLY = false;

// 🔮 ساختارِ خوانشِ v4 (v3.5.0) — بازطراحیِ کاملِ شکلِ خروجی بر اساسِ تحلیلِ خوانش‌های
// واقعیِ انسانی + دو تحقیقِ مستقل. جزئیات و وزنِ منابع در bots/tarot/STYLE.md.
// سه تغییرِ ساختاری:
//   ۱) افشا = تیزرِ کوتاه per کارت (چند کلمه، درباره‌ی خودِ کارت) تا تعلیق حفظ شود
//   ۲) متنِ نهایی با **سرخطِ جواب** شروع می‌شود، نه با روایت
//   ۳) بازخورد از وسطِ خوانش به آخرِ کار منتقل شد و مقیاسِ ۱ تا ۵ گرفت
// ✅ از v3.7.0 برای **همه‌ی کاربران** باز است. مسیرِ مرحله‌ای طبق بند ۲ج-۲ ریشه کامل طی شد:
// از v3.5.0 تا v3.6.7 فقط اکانتِ ادمین آن را می‌دید. در این فاصله ۱۶ دورِ آزمایشگاه روی
// ~۳۰۰ فال اجرا شد (جمله‌ی بی‌لنگر ۲۴٪ → ۱۸٪، ایرادِ سخت به ~۱ از ۲۷ رسید و دسته‌ی
// غالبش از بین رفت)، و در آخر مالک دستی تست کرد و تأیید کرد (۱۴۰۵/۰۵/۲۷).
// Rollback فوری و بدونِ فکر: `READING_V4 = false` → دقیقاً به خوانشِ v3 برمی‌گردد
// (پرامپت، افشا، بازخورد، همه). مسیرِ v3 عمداً هنوز پاک نشده — بندِ ۹/۰ ریشه می‌گوید
// کدِ رول‌بک بعد از باز شدن پاک می‌شود، ولی بندِ ۲ج/۸ رول‌بکِ یک‌خطی را واجب می‌داند؛
// پس حذفِ v3 یک PR جداست، بعد از اینکه این لانچ چند روز پایدار ماند.
const READING_V4 = true;
const READING_V4_ADMIN_ONLY = false;
const v4For = (uid) => READING_V4 && (!READING_V4_ADMIN_ONLY || isTester(uid));
// نشانه‌ی ابتدای هر بخشِ متنِ نهایی. عمداً در **کد** است نه در پرامپت: مدل اگر آزاد
// باشد هر بار سلیقه‌ای ایموجی می‌پاشد؛ این‌طوری ثابت، کم و قابلِ‌تغییر از یک نقطه است.
// (خوانش‌های واقعیِ انسانی اصلاً ایموجی ندارند؛ این یک انتخابِ آگاهانه‌ی محصولی است تا
// متنِ بلندِ تلگرام بخش‌بندیِ چشمی داشته باشد و دیوارِ متن نباشد.)
// نشانه‌های بخش (`SECT`)، برداشتنِ برچسبِ کارت (`stripCardLabel`)، فیلترِ خط تیره
// (`noDash`) و فاصله‌ی زمانیِ فارسی (`agoFa`) همگی به `reading-core.js` منتقل شدند تا
// آزمایشگاهِ آفلاین همان‌ها را اجرا کند. رفتارشان ذره‌ای عوض نشده.

// 🎙 سؤالِ صوتی مستقیم به مدل (v3.4.0): تا قبل از این، ویس **دو** فراخوانی می‌شد — یکی
// رونویسی و یکی خوانش. حالا خودِ فایلِ صوتی کنارِ پرامپت به Gemini می‌رود و کلِ کار **یک**
// فراخوانی است. مدل متنِ سؤال را هم در `question_text` برمی‌گرداند تا رکوردِ فال مثل قبل
// سؤال را داشته باشد (پشتیبانی/دیباگ) بدونِ اینکه فراخوانیِ دومی لازم باشد.
// Rollback یک‌خطی: false → برمی‌گردیم به مسیرِ رونویسی، ولی **همچنان بعد از پرداخت**
// (قاعده‌ی هزینه پایین‌تر مستقل از این پرچم است و با آن رول‌بک نمی‌شود).
const AUDIO_DIRECT_ENABLED = true;
/* 🎙 ولی «مسیرِ مستقیمِ صدا» فقط وقتی ممکن است که مدلِ خوانش **واقعاً صدا بفهمد**.
 * این یک تضمینِ ساختاری است، نه یک قاعده‌ای که کسی باید یادش بماند: از خودِ مدلِ
 * پیکربندی‌شده مشتق می‌شود، پس روزی که مدل عوض شود مسیر خودبه‌خود درست می‌ماند.
 * ⚠️ چرا لازم شد: آزمایشگاه `openai/gpt-5.6-luna` را برای زبان‌های غیرفارسی برنده
 * کرد و آن مدل ورودیِ صوتی نمی‌گیرد. بدونِ این گارد، اولین فالِ صوتیِ روسی **بعد
 * از کسرِ اعتبار** به مدلی می‌رفت که نمی‌تواند بشنود؛ یعنی خرابی دقیقاً در گران‌ترین
 * نقطه‌ی ممکن. با این گارد، همان کاربر بی‌سروصدا به مسیرِ «رونویسی بعد خوانش»
 * می‌رود که از قبل ساخته شده و آزموده است.
 * فهرست عمداً allowlist است نه denylist: مدلِ ناشناخته «نمی‌شنود» فرض می‌شود، چون
 * حدسِ اشتباه در این جهت فقط یک فراخوانیِ ارزانِ اضافه است، ولی در جهتِ دیگر یک
 * فالِ پول‌داده‌ی شکسته. */
const AUDIO_CAPABLE = [/^google\/gemini/i];
/* 🐛 برچسبِ فرمتِ صدا. تا ۱۴۰۵/۰۶/۱۰ این یک خط بود:
 *     fmt: /wav/i.test(mime) ? 'wav' : 'mp3'
 * یعنی ویسِ تلگرام که همیشه **ogg/opus** است با برچسبِ **mp3** فرستاده می‌شد. روی
 * مسیرِ chat completionsِ جمنای ظاهراً کار می‌کرد (بایت را خودش می‌شناسد)، پس سال‌ها
 * بی‌صدا ماند. ولی endpointِ اختصاصیِ رونویسی برچسب را جدی می‌گیرد و بایتِ ogg با
 * برچسبِ mp3 را رد یا بد-دیکد می‌کند. یعنی لحظه‌ای که پله‌ی ویسپر روشن شود، فالبک
 * **همیشه** شکست می‌خورد و هیچ‌کس نمی‌فهمد — همان کلاسِ «فالبکِ مرده‌ی بی‌صدا» که
 * دورِ هشتمِ روسی هم داشت. این باگ در I18N-ES-STT-RESEARCH.md بندِ ۹ ثبت شده بود
 * به‌عنوانِ «بمبِ ساعتیِ خاموش»؛ حالا که ساعتش رسید، خنثی شد. */
const AUDIO_FORMATS = [
  // نگاشت روی **ظرف** است نه کدک: `audio/webm; codecs=opus` باید webm بدهد نه ogg.
  [/ogg/i, 'ogg'], [/wav/i, 'wav'], [/mpeg|mp3/i, 'mp3'],
  [/mp4|m4a|aac/i, 'm4a'], [/webm/i, 'webm'], [/flac/i, 'flac'],
];
// پیش‌فرض ogg است نه mp3: ویسِ تلگرام همیشه ogg/opus است و این مسیر فقط ویس می‌گیرد.
const audioFormatOf = (mime) => AUDIO_FORMATS.find(([re]) => re.test(mime || ''))?.[1] || 'ogg';
const READER_HEARS_AUDIO = AUDIO_CAPABLE.some((re) => re.test(READING_MODEL));
const audioDirectOn = () => AUDIO_DIRECT_ENABLED && READER_HEARS_AUDIO;
const toneV2For = (uid) => READING_TONE_V2 && (!READING_TONE_V2_ADMIN_ONLY || isTester(uid));

// ───────────────────────────────────────────────────────────────────────────
// 🧭 UX v2 (v3.8.0) — بازطراحیِ بنیادیِ سفرِ کاربر
// ───────────────────────────────────────────────────────────────────────────
// یک پرچم برای **کلِ** بازطراحی، نه یکی per تغییر. دلیل: این ده تغییر به هم وابسته‌اند
// (ماهِ تولد ورودیِ کارتِ روز است، الماس واحدِ کاتالوگِ جدید است، حذفِ موضوع یعنی کاتالوگِ
// جدید). اگر هرکدام پرچمِ خودش را داشت، ترکیب‌های نیمه‌روشن ممکن می‌شد که هیچ‌وقت تست
// نشده‌اند. یک پرچم یعنی دقیقاً دو حالتِ ممکن: دنیای قدیم، یا دنیای نو.
//
// چه چیزی عوض می‌شود:
//   ۱) آنبوردینگ: «ذهنت درگیر چیه؟» → «ماه تولدت چیه؟»
//   ۲) کاتالوگ: موضوع‌ها حذف؛ فقط سه فال بر اساسِ **اندازه** (۳/۵/۱۰ کارت)
//   ۳) کاربر **همه‌ی** کارت‌ها را خودش می‌چیند (نه سه‌تا و بقیه خودکار)
//   ۴) کیف پول → الماس‌فروشی با سه بسته
//   ۵) هدیه‌ها و پاداش‌ها به الماس
//   ۶) کارتِ روز: انتخابِ کارت توسط کاربر + متنِ از-پیش-نوشته (بدونِ LLM)
//
// ✅ **از v3.25.0 (۱۴۰۵/۰۵/۳۰) برای همه‌ی کاربران باز است.** مسیرِ بند ۲ج-۲ ریشه کامل طی
// شد: از v3.8.0 تا v3.24.0 فقط ادمین و تسترها، و باز کردنش در همین PR با مهاجرتِ موجودی
// و پیامِ اطلاع‌رسانی همراه بود. پیش‌نیازهایی که **قبل** از این خط اجرا شدند:
//   ۱) `tools/coin-migration-tarot.mjs --apply` — موجودیِ تومانی به الماس تبدیل شد،
//      وگرنه کاربر عددی می‌دید که با کیفش نمی‌خواند.
//   ۲) پنجره‌ی یک‌باره‌ی مهاجرتِ کیبورد (`KB_V2_EPOCH` در `ensureMenu`) — وگرنه کاربرِ
//      فعلی کیبوردِ تومانیِ قدیمی را نگه می‌داشت و «کارت شانس» را اصلاً نمی‌دید.
// Rollback فوری: `UX_V2 = false` → همه‌چیز دقیقاً به سفرِ قبلی برمی‌گردد. ستونِ
// جدیدِ `users.birth_month` و جدولِ `daily_log` می‌مانند ولی خوانده نمی‌شوند، پس
// مهاجرتِ برگشتی لازم نیست (بند ۲ج/۱: فقط افزایشی). ستونِ `coins` عمداً ساخته نشد:
// موجودی همچنان تومان است و الماس فقط واحدِ نمایش (بند ۹ ریشه، منبعِ حقیقتِ پول یکی است).
const UX_V2 = true;
const UX_V2_ADMIN_ONLY = false;
const uxV2For = (uid) => UX_V2 && (!UX_V2_ADMIN_ONLY || isTester(uid));

// ───────────────────────────────────────────────────────────────────────────
// 🪙 اقتصادِ سکه (v3.0.0)
// ───────────────────────────────────────────────────────────────────────────
// موجودیِ داخلی **همچنان تومان** است (منبعِ حقیقتِ پول عوض نمی‌شود؛ بند ۹ ریشه). الماس فقط
// واحدِ نمایش است: هر کارت = ۱ الماس. چون قانونِ قیمت از قبل «هر کارت
// ۱۰٬۰۰۰ تومان» بود، `coins = spread.size` بدونِ هیچ عددِ جدیدی درمی‌آید و هیچ قیمتی دو
// جا نوشته نمی‌شود. هدیه‌ی خوش‌آمدِ ۳۰٬۰۰۰ هم دقیقاً ۳ الماس است، یعنی یک فالِ کامل.
//
// ⚠️ فعلاً فقط ادمین. باز کردن برای همه = `COIN_ECONOMY_ADMIN_ONLY = false`.
// Rollback فوری: `COIN_ECONOMY = false` → کاتالوگ، کیف‌پول و همه‌ی متن‌ها به تومان برمی‌گردند
// (الماس هیچ ستونی در DB ندارد، پس چیزی برای مهاجرتِ برگشتی وجود ندارد).
// ⏸ **پارک‌شده (۱۴۰۵/۰۵/۲۴ — تصمیمِ مالک).** کدش عمداً حذف نشد چون به‌زودی دوباره
// رویش کار می‌کنیم؛ فقط پرچم خاموش است، پس حتی ادمین هم دنیای تومانیِ قبلی را می‌بیند.
// چون کاتالوگِ نسل دوم (عشق‌محورِ تقابلی) هم از همین helper شاخه می‌گیرد، خاموش‌کردنِ
// این یک پرچم **هر دو** را با هم به حالتِ قبل برمی‌گرداند.
// روشن‌کردنِ دوباره: `COIN_ECONOMY = true` (+ bump نسخه). **آن موقع فقط «الماس» می‌ماند و
// «فال‌گیر» کلاً حذف است** — آزمایشِ نامِ واحد منحل شد.
const COIN_ECONOMY = false;
const COIN_ECONOMY_ADMIN_ONLY = true;
// 💎 دیگر هیچ ضریبی وجود ندارد: عددِ داخلِ دیتابیس **خودِ تعدادِ الماس** است.
// (مهاجرتِ `tools/coins-native-tarot.mjs`، ۱۴۰۵/۰۵/۳۰). دلیلِ حذف: قیمتِ هر الماس به
// بسته بستگی دارد (۳٬۰۰۰ / ۲٬۰۰۰ / ۱٬۵۰۰ تومان)، پس هیچ نرخِ واحدی وجود نداشت و آن
// ضریب یک دروغِ ماندگار در دیتا بود.
// UX v2 ذاتاً الماسی است (کاتالوگ و الماس‌فروشی هر دو به الماس حرف می‌زنند)، پس پرچمِ
// جداگانه‌ی الماس را هم روشن می‌کند. پرچمِ قدیم برای دنیای قبل سرِ جایش می‌ماند.
const coinsOn = (uid) => uxV2For(uid) || (COIN_ECONOMY && (!COIN_ECONOMY_ADMIN_ONLY || isTester(uid)));

// ───────────────────────────────────────────────────────────────────────────
// ⭐ سوییچِ استارز per-فاکتور — فقط فارسی (v3.76.0)
// ───────────────────────────────────────────────────────────────────────────
// خواسته‌ی صریحِ مالک: «به‌صورتِ آزمایشی اضافه شود تا میزانِ استقبال سنجیده شود».
// طبقِ الگوی مستندِ بند ۲ج-۲ ریشه («اول فقط ادمین، بعد همه»): دو ثابتِ جدا، نه یکی.
// باز کردن برای همه = `FEATURE_STARS_TOGGLE_ADMIN_ONLY = false` در یک PRِ جدا (بعد از
// چند روز تستِ دستیِ مالک) + bump نسخه. رول‌بکِ فوری: `FEATURE_STARS_TOGGLE = false`.
// ⚠️ این با `starsRail` **اصلاً همان چیز نیست**: `starsRail` یک ثابتِ سطحِ زبان است
// (بند ۲و/۴ ریشه) و فقط برای ru/pt/es true می‌شود؛ این‌جا برعکس — دقیقاً برای رباتِ
// فارسی (`starsRail === false`) یک مسیرِ **موازیِ اضافه** باز می‌شود، بدونِ اینکه هیچ
// کدِ starsRail-محورِ موجود (پکِ farsiOnly، STARS_EXPERIMENT، …) لمس شود.
/* 🔇 خاموش از v3.81.0 — تصمیمِ مالک روی **دیتا**، نه حدس.
 *
 * این فیچر از v3.76.0 (۱۰ روز) فقط-ادمین زنده بود تا «میزانِ استقبال سنجیده شود».
 * جوابِ دیتا قاطع بود: `stars_toggle_at IS NOT NULL` روی کلِ جدولِ `payments` **صفر**
 * ردیف دارد — یعنی حتی یک بار هم زده نشد، نه توسط کاربر و نه توسط خودِ مالک روی
 * فاکتورِ واقعی. پس آزمایش تمام شد و نتیجه‌اش «استفاده نشد» است.
 *
 * ⚠️ عمداً **حذف نشد** (خواسته‌ی صریحِ مالک: «کدها را پاک نکن»). این استثنای ثبت‌شده‌ی
 * بند ۹/۰ است: مسیرِ برگشت کدِ مرده نیست تا وقتی تصمیمِ نهایی گرفته نشده. برگرداندن =
 * همین یک خط `true`.
 *
 * و چرا این خاموشی روی مسیرِ پول امن است: صفر ردیفِ سوییچ‌شده یعنی هیچ فاکتورِ نیتیوِ
 * استارزی در جریان نیست، پس خاموش شدنِ `registerStarsPay` برای fa هیچ پرداختِ معلقی را
 * بی‌صاحب نمی‌گذارد. دکمه‌ی کش‌شده هم بی‌خطر است: خودِ هندلرِ `stars_toggle` اولین کارش
 * `if (!starsToggleOn(uid)) return` است (بند ۲ج/۶). */
const FEATURE_STARS_TOGGLE = false;
const FEATURE_STARS_TOGGLE_ADMIN_ONLY = true;
const starsToggleOn = (uid) => !starsRail && FEATURE_STARS_TOGGLE
  && (!FEATURE_STARS_TOGGLE_ADMIN_ONLY || isAdmin(uid));

/* 🛑 مسیرهای پرداختِ **نسلِ تومانی** بسته‌اند.
 * `setRechargeAmount` و `invoiceForReading` هر دو فرض می‌کنند «تومانِ پرداختی = اعتبارِ
 * داده‌شده» (نسبتِ ۱:۱ دنیای تومانی). در دنیای الماس این فرض غلط است: فاکتور تومان است
 * ولی اعتبار الماس. بعد از مهاجرتِ «الماسِ بومی» این‌ها فعالانه خطرناک شدند — یک دکمه‌ی
 * کش‌شده‌ی `ramt:50000` در چتِ یک کاربرِ قدیمی یعنی فاکتورِ ۵۰٬۰۰۰ **الماس**.
 * از UI امروز هیچ‌کدام ساخته نمی‌شوند (کیف فقط بسته می‌فروشد)، ولی دکمه‌ی کهنه سال‌ها
 * زنده می‌ماند (بند ۲ج/۶)، پس به‌جای مرگِ بی‌صدا پیامِ مودبانه می‌گیرد. */
const legacyTomanPay = (uid) => coinsOn(uid);

// آزمایشِ نامِ واحد (الماس در برابر فال‌گیر) **منحل شد**: «فال‌گیر» در عمل بد جا می‌افتاد.
// واحد از این به بعد فقط «الماس 🪙» است. کلید را نگه می‌داریم تا بتوانیم آزمایش را در DB
// صراحتاً stop کنیم (وگرنه در داشبورد «در حال اجرا»ی دروغین می‌ماند).
const AB_COIN_NAME = 'coin_name';
// آبجکتِ ارز که به همه‌ی متن‌های locale پاس داده می‌شود. `on:false` یعنی «دقیقاً مثل قبل، تومان».
const TOMAN_CUR = { on: false, value: 1, name: 'تومان', emoji: '' };
function curOf(uid) {
  if (!coinsOn(uid)) return TOMAN_CUR;
  return { on: true, value: 1, name: L.coinUnit.name, emoji: L.coinUnit.emoji };
}
// سه بسته‌ی خریدِ الماس (تصمیمِ مالک). قیمت‌ها **تومانِ واقعی**اند و `coins` همان
// اعتباری است که به موجودیِ کاربر اضافه می‌شود، یعنی هر بسته ذاتاً تخفیف‌دار است و بسته‌ی بزرگ‌تر
// هر الماس را ارزان‌تر می‌کند (نردبانِ ARPU). هیچ مرحله‌ی «چقدر شارژ کنم؟» در کار نیست.
/* 🧪 آزمایشِ رنگِ CTAهای مالی. کنترل عمداً «بی‌رنگ» است، یعنی رفتارِ امنِ فعلی؛
 * treatment با نام `colored` همان رنگ‌بندیِ پیشین را برمی‌گرداند. تخصیص به بازوی
 * قیمت لایه‌بندی می‌شود تا قیمت و رنگ در تحلیل با هم قاطی نشوند. تا وقتی آزمایش از
 * داشبورد running نشود، همه control/بی‌رنگ می‌مانند. */
const MONEY_CTA_STYLE_EXPERIMENT = 'money_cta_style_v1';
const MONEY_CTA_COLORED_VARIANT = 'colored';
const PACK_STYLE = { gold: 'success', magic: 'primary', legend: 'danger', eternal: 'danger' };
/* 📦 بسته‌ها فقط **داده** هستند: کلیدِ پایدار، ایموجی، تعدادِ الماس و قیمت.
 * نامِ نمایشی عمداً این‌جا نیست و در `locales/<lang>.js` نشسته، چون یک متنِ
 * رو-به-کاربر است و هر زبان باید مالِ خودش را داشته باشد (بند ۲و). */
const COIN_PACKAGES = [
  /* 💰 **قیمت‌ها به قبل از v3.75.0 برگشتند** (v3.78.0، تصمیمِ صریحِ مالک).
   *
   * v3.75.0 قیمت را ۳۰k/۶۰k/۱۵۰k ⟵ ۵۰k/۹۰k/۱۹۰k کرد. تحلیلِ سه‌روزه
   * (`analytics/tarot/reports/2026-09-10-revenue-drop.md`) نشان داد **نرخِ بستنِ فاکتور**
   * — یعنی پرداختِ تأییدشده ÷ کسی که صفحه‌ی بسته‌ها را دید — از ۱۱٫۷٪ به ۴٫۴٪ افتاد
   * (z=۲٫۶۳، p=۰٫۰۰۹) در حالی که نرخِ **رسیدنِ** کاربر به همان صفحه اصلاً تکان نخورد
   * (۱۹٫۲٪ ⟵ ۱۹٫۰٪). یعنی قیف بالادست سالم بود و ریزش دقیقاً سرِ قیمت اتفاق می‌افتاد.
   * میانگینِ فاکتور ۲۲٪ بزرگ‌تر شد ولی تعدادِ پرداخت‌کننده ۲٫۷ برابر کوچک‌تر، پس
   * درآمد به ازای هر بازدیدکننده‌ی این صفحه از ۷٬۷۳۰ به ۳٬۳۵۰ تومان رسید.
   *
   * ⚠️ تعدادِ الماسِ هر بسته در هر دو نسخه دست‌نخورده بود و الان هم هست، پس قراردادِ
   * «هدیه‌ی خوش‌آمد = بهای دقیقِ یک فالِ سه‌کارتی» (بند بالای WELCOME_BONUS_COINS_V2)
   * به این ستون کاری ندارد و هدیه‌ی ۳ الماس سرِ جایش می‌ماند.
   *
   * ⚠️ فاکتورِ **بازِ** صادرشده با قیمتِ v3.75.0 معتبر می‌ماند و با همان مبلغ تأیید
   * می‌شود: `amount` روی خودِ ردیف نشسته و هیچ مسیری قیمت را از این آرایه دوباره
   * نمی‌خواند (بند ۲ج/۵ ریشه).
   *
   * 💰 **کفِ بسته‌ی معمولی ۳۰k ⟵ ۱۵k رفت (v3.91.0)** — نتیجه‌ی فاز ۱ِ آزمایشِ نردبانِ
   * قیمت (بخشِ پایینِ همین فایل): `floor` با نسبتِ ۲٫۲۳ برابر برنده شد (z=۲٫۷۰،
   * p=۰٫۰۰۷، CTW ۹۹٫۷٪)، بدونِ افتِ حاشیه و بدونِ هم‌نوع‌خواریِ بسته‌های دیگر. تصمیمِ
   * صریحِ مالک: اعمال روی همه، بدونِ فازِ دوم فعلاً. چون این آرایه همان چیزی است که
   * `PRICE_LADDERS.control` به آن ارجاع می‌دهد (پایین‌تر)، همین یک خط کافی بود —
   * فاز ۱ همین‌جا مستقیماً «بازوِ برنده در کد نشست» را برآورده کرد. */
  { key: 'basic',  emoji: '🥉', coins: 5,   toman: 15_000 },
  // ایموجیِ بسته‌ی وسط 💠 است و عمداً **خودِ 💎 نیست**: در همان دکمه ایموجیِ واحد هم
  // می‌آید و دو 💎 پشت‌سرهم بد خوانده می‌شود. نامش از «بسته‌ی الماسی» به «بسته ویژه»
  // رفت (تصمیمِ مالک): «الماسی» با واحدِ الماس اشتباه گرفته می‌شد، انگار فقط این یکی
  // بسته الماس می‌دهد. کلیدِ `gold` عوض نشد چون در `payments.package_key` کاربرانِ
  // واقعی نشسته و بند ۲ج/۱ تغییرِ معنیِ داده‌ی موجود را ممنوع کرده.
  { key: 'gold',   emoji: '💠', coins: 30,  toman: 60_000 },
  { key: 'magic',  emoji: '🪄', coins: 100, toman: 150_000 },
];

/* 🗄 **دو بسته‌ی گران — خاموش، نه حذف‌شده** (v3.78.0، تصمیمِ صریحِ مالک).
 *
 * «افسانه‌ای» و «جاودان» در v3.75.0 اضافه شدند و از فروشگاه برداشته شدند چون در کلِ
 * عمرشان **صفر** فروش داشتند (و در همان بازه بسته‌ی ۱۹۰k هم صفر)، یعنی منوی گران‌تر
 * فقط لنگرِ قیمت را بالا می‌برد بدونِ اینکه چیزی بفروشد.
 *
 * ⚠️ **تعریفشان عمداً کامل مانده و کدِ نمایششان هم پاک نشده** (خواسته‌ی صریحِ مالک:
 * «شاید بعداً برشان گردانیم»). راهِ برگشت **یک خط** است: `EXTRA_PACKS_ENABLED = true`.
 * همان لحظه هم دوباره در فروشگاه می‌آیند، هم آزمایشِ نمایششان (`pack_reveal_v1`)
 * دوباره زنده می‌شود؛ هیچ چیزِ دیگری لازم نیست.
 *
 * 🚨 ولی قبل از روشن‌کردن **قیمتشان باید بازچینی شود**: با قیمت‌های برگشته‌ی
 * ۳۰k/۶۰k/۱۵۰k، نردبانِ «بسته‌ی بزرگ‌تر = هر الماس ارزان‌تر» می‌شکند —
 * ۴۹۰k÷۳۰۰ = ۱٬۶۳۳ تومان per الماس، یعنی **گران‌تر** از ۱۵۰k÷۱۰۰ = ۱٬۵۰۰. این دو
 * برای دنیای ۵۰k/۹۰k/۱۹۰k چیده شده بودند. چکِ CI همین را قفل کرده و اگر پرچم بدونِ
 * بازچینیِ قیمت روشن شود، قرمز می‌دهد.
 *
 * ⚠️ کلیدشان در هر دو حالت وارد `PACKAGE_BY_KEY` می‌شود، چون حتی وقتی خاموش‌اند:
 *   ۱) ردیفِ پرداختِ بازِ `pkg='legend'` باید نامِ بسته‌اش را روی فاکتور و در پیامِ
 *      ادمین نگه دارد (بند ۲ج/۵: فلوی pending با شرایطِ قبلی معتبر می‌ماند). عددِ
 *      الماس از `original_amount` می‌آید نه از این‌جا، پس واریز هرگز به این وابسته نیست.
 *   ۲) دکمه‌ی inline در چتِ کاربر نمی‌میرد (بند ۲ج/۶) و تپ روی آن باید پیامِ مودبانه
 *      بگیرد، نه سکوتِ محض روی مسیرِ پول. `isRetiredPack` همین را ممکن می‌کند. */
const EXTRA_PACKS_ENABLED = false;
const EXTRA_PACKAGES = [
  /* 🆕 عمداً **فقط ریلِ کارت** (`farsiOnly`): اقتصادِ استارزِ ru/pt/es
   * (`STAR_LADDERS`/`LADDER_RATIO` در starspay.js) فقط سه بسته را می‌شناسد و خواسته‌ی
   * مالک هم صراحتاً «قیمتِ فارسی» بود، نه استارز. اگر این دو بدونِ گارد به رندرِ استارز
   * می‌رسیدند، تپِ کاربر با خطای عمومی رد می‌شد (`starsFor` نال می‌دهد) — یعنی یک
   * دکمه‌ی دیده‌شده‌ی بی‌اثر روی مسیرِ پول. پس فیلترِ `farsiOnly` هم در رندر
   * (`packMenuScreen`) هم در اکشنِ `pkg:` تکرار شده. */
  { key: 'legend',  emoji: '🌌', coins: 300,  toman: 490_000,   farsiOnly: true },
  { key: 'eternal', emoji: '👑', coins: 1000, toman: 1_490_000, farsiOnly: true },
];
const PACKAGE_BY_KEY = Object.fromEntries(
  [...COIN_PACKAGES, ...EXTRA_PACKAGES].map(p => [p.key, p]));
const EXTRA_PACK_KEYS = new Set(EXTRA_PACKAGES.map(p => p.key));
const isRetiredPack = (key) => !EXTRA_PACKS_ENABLED && EXTRA_PACK_KEYS.has(key);

/* ─────────────────────── 💰 آزمایشِ نردبانِ قیمت (v3.80.0) ───────────────────────
 *
 * سه نردبانِ کامل، نه سه «تخفیف». هر بازو یک کاتالوگِ مستقل است تا `pkg:` و فاکتور و
 * دکمه همه از **یک** آبجکت بخوانند؛ محاسبه‌ی درجای قیمت یعنی دو منبعِ حقیقت و همان
 * کلاسِ باگِ ثبت‌شده‌ی بند ۲و/۶ج («عدد و واحد از دو جا بیایند، یکی عوض می‌شود و آن یکی
 * ساکت می‌ماند»).
 *
 * 🎯 دو متغیرِ **جدا**، هر کدام در یک پله — عمداً، وگرنه نتیجه تفسیرپذیر نیست:
 *   control ⟶ floor : فقط **اندازه‌ی کوچک‌ترین بلیت** (۳۰k ⟶ ۱۵k). قیمتِ هر الماس در
 *                     هر سه بسته **بیت‌به‌بیت** همان control است (۳۰۰۰/۲۰۰۰/۱۵۰۰)، پس
 *                     این بازو فقط می‌پرسد «کفِ پایین‌تر خریدار می‌آورد؟» و هیچ ادعای
 *                     ارزان‌تر بودنی نمی‌کند.
 *   floor   ⟶ cheap : فقط **سطحِ قیمت**. تعدادِ الماسِ هر سه بسته با floor یکی است
 *                     (۵/۳۰/۱۰۰) و فقط تومانش ~۳۰٪ پایین‌تر (۲۰۰۰/۱۵۰۰/۱۰۰۰).
 * اگر بسته‌ی وسطِ cheap مثل پیشنهادِ اولیه ۲۰💎/۳۰k می‌شد، بینِ floor و cheap **هم**
 * تعدادِ الماس عوض می‌شد **هم** قیمت، و افت/رشدِ فروش را نمی‌شد به هیچ‌کدام نسبت داد.
 *
 * ⚠️ ناوردای نردبان (`check-coins`) در **هر سه** بازو برقرار است: بسته‌ی بزرگ‌تر =
 * هر الماس ارزان‌تر. `tools/check-price-ladder.mjs` هر سه را می‌سنجد، نه فقط کاتالوگِ
 * زنده را. */
// ⚠️ v3.91.0: `control` و `floor` از این نسخه **بیت‌به‌بیت یکی**اند — عمداً، نه باگ.
// فاز ۱ تمام شد و `floor` برنده شد، پس نردبانش در `COIN_PACKAGES` بالا نشست و
// `control` (که ارجاع به همان آرایه است) خودکار همان مقدار را گرفت. `floor` این‌جا
// عمداً پاک نشد: مستندِ تاریخیِ «چه چیزی آزمایش و برنده شد» است و ورودیِ آماده‌ی
// یک مقایسه‌ی احتمالیِ آینده. تنها بازوی زنده‌ی امروز `cheap` است.
const PRICE_LADDERS = {
  control: COIN_PACKAGES,                                     // ۳۰۰۰ / ۲۰۰۰ / ۱۵۰۰ تومان per الماس
  floor: [
    { key: 'basic', emoji: '🥉', coins: 5,   toman: 15_000 },  // ۳۰۰۰ — دقیقاً نرخِ control
    { key: 'gold',  emoji: '💠', coins: 30,  toman: 60_000 },  // ۲۰۰۰ — دست‌نخورده
    { key: 'magic', emoji: '🪄', coins: 100, toman: 150_000 }, // ۱۵۰۰ — دست‌نخورده
  ],
  cheap: [
    { key: 'basic', emoji: '🥉', coins: 5,   toman: 10_000 },  // ۲۰۰۰
    { key: 'gold',  emoji: '💠', coins: 30,  toman: 45_000 },  // ۱۵۰۰
    { key: 'magic', emoji: '🪄', coins: 100, toman: 100_000 }, // ۱۰۰۰
  ],
  /* 🆕 `bulk` (`price_ladder_p3`، v3.94.0) — فرضیه‌ی تازه‌ی مالک، مستقلِ کاملاً از
   * فاز ۱/۲ بالا: به‌جای ارزان‌ترکردنِ تومان، **حجمِ الماسِ** بسته‌های میانی و بالا
   * چند برابر شد تا کاربر با یک عددِ الماسِ بزرگ‌تر ترغیبِ خرید شود. `basic` عمداً
   * دست‌نخورده ماند (کنترل، همان کاتالوگِ زنده‌ی امروز) — تنها متغیرِ این آزمایش
   * دو بسته‌ی بالاتر است. ناوردای نردبان («بزرگ‌تر = هر الماس ارزان‌تر») همچنان
   * برقرار است: ۳۰۰۰ ⟶ ۱۵۰۰ ⟶ ۷۵۰ تومان per الماس. */
  bulk: [
    { key: 'basic', emoji: '🥉', coins: 5,    toman: 15_000 },    // ۳۰۰۰ — همان control
    { key: 'gold',  emoji: '💠', coins: 100,  toman: 150_000 },   // ۱۵۰۰
    { key: 'magic', emoji: '🪄', coins: 2000, toman: 1_500_000 }, // ۷۵۰
  ],
};

/* 🔑 **دو کلید، نه یک کلید با وزنِ متغیر** — و این تصمیمِ روشیِ اصلیِ این PR است.
 *
 * خودِ `shared/ab.js` در هدرش نوشته «وزن‌ها بعد از start فریز می‌شوند؛ تغییر وزن =
 * آزمایشِ جدید». دلیلش این‌جا کاملاً عملی است: `ab_exposures` **چسبنده** است، پس اگر
 * فازِ دوم را با عوض‌کردنِ وزنِ همان کلید بزنیم، کاربرانِ فازِ اول شاخه‌شان را نگه
 * می‌دارند و بازوی «برنده» ترکیبی از «۳ روز است این قیمت را می‌بیند» و «تازه رسیده»
 * می‌شود، در حالی که بازوی مقابل کاملاً تازه است. این دقیقاً همان **سوگیریِ نامتقارن**
 * است که بند ۲الف ریشه (جاروی یادآوریِ شبانه) ثبتش کرده — نه نویز، که با نمونه‌ی
 * بیشتر پاک شود.
 *
 * با کلیدِ جدا، فازِ دوم یک تصادفی‌سازیِ **تمیز** است: هر دو بازو از صفر.
 *
 * ترتیبِ آرایه = اولویت (فازِ جدیدتر اول). کدام کلید فعال است از خودِ جدولِ
 * `experiments` خوانده می‌شود، پس **ترتیبِ فازها یک تصمیمِ داشبورد است نه یک دیپلوی**:
 * مالک فاز ۱ را stop و فاز ۲ را با وزنِ دلخواه start می‌کند و همان لحظه (≤۶۰ ثانیه)
 * اثر می‌کند. اگر برنده‌ی فاز ۱ خودِ control بود، فاز ۲ وزنِ `control`/`cheap` می‌گیرد؛
 * اگر `floor` بود، وزنِ `floor`/`cheap`. هیچ‌کدام کد لازم ندارد.
 *
 * 🏁 **فاز ۱ تمام شد (v3.91.0).** `floor` برنده اعلام شد، در `COIN_PACKAGES` بالا
 * نشست، و `price_ladder_p1` بلافاصله بعد از تأییدِ زنده‌بودنِ همین دیپلوی از داشبورد/
 * Ops با `{"op":"status","key":"price_ladder_p1","to":"stopped"}` بسته می‌شود —
 * حالا کاملاً بی‌خطر، چون `stopped` همه را به `control` برمی‌گرداند و `control` دیگر
 * همان بازنده‌ی قدیم نیست، بیت‌به‌بیت همان `floor` است.
 * ⛔ **فاز ۲ (بازوی `cheap`) هنوز شروع نشده.** `cheap` و کلِ این زیرساخت
 * (`PRICE_LADDERS`, `priceArm`, `exposePrice`) عمداً پاک نشدند: اگر/وقتی مالک آن
 * فرضیه را هم خواست، دقیقاً `price_ladder_p2` است، `control`(=floor امروز) در
 * برابرِ `cheap`، بدونِ نیازِ به هیچ تغییرِ کد — فقط ساختن و start از داشبورد.
 *
 * 🆕 **`price_ladder_p3` (v3.94.0) یک فرضیه‌ی کاملاً جداست، نه ادامه‌ی فازِ ۲.**
 * `bulk` (بالا) را در برابرِ `control` می‌سنجد: به‌جای ارزان‌ترکردنِ تومان، حجمِ
 * الماسِ بسته‌های میانی/بالا چند برابر شد. چون کلیدش جداست، شروعش هیچ اثری روی
 * تصمیمِ ثبت‌شده‌ی فازِ ۲ (که هنوز `not started` است) ندارد. */
const PRICE_EXPERIMENTS = ['price_ladder_p3', 'price_ladder_p2', 'price_ladder_p1'];
let _priceExpStmt = null;
let _priceExpCache = { at: 0, key: null };
/* کلیدِ آزمایشِ قیمتی که همین حالا زنده است (یا null). کشِ ۶۰ثانیه‌ای عمداً هم‌اندازه‌ی
 * کشِ خودِ `shared/ab.js` است تا kill switch در هر دو لایه یک تأخیر داشته باشد.
 * ⚠️ statement تنبل ساخته می‌شود چون `db` چند صد خط پایین‌تر تعریف شده؛ این تابع فقط
 * در زمانِ اجرا (بعد از بوت) صدا زده می‌شود. */
const activePriceExperiment = () => {
  const now = Date.now();
  if (now - _priceExpCache.at < 60_000) return _priceExpCache.key;
  let key = null;
  try {
    if (!_priceExpStmt) _priceExpStmt = db.prepare(
      "SELECT key FROM experiments WHERE key=? AND status IN ('running','draining')");
    for (const k of PRICE_EXPERIMENTS) if (_priceExpStmt.get(k)) { key = k; break; }
  } catch (e) { logErr('price exp:', e.message); }
  _priceExpCache = { at: now, key };
  return key;
};

/* بازوی قیمتِ این کاربر. **هر خطا و هر ابهام → control**، یعنی دقیقاً قیمت‌های امروز
 * (بند ۲ج/۴: کنترل = رفتارِ قبلی، و بدونِ آزمایشِ running هیچ‌کس از control بیرون نمی‌رود).
 *
 * ⚠️ `starsRail` (ru/pt/es) **همیشه** control است و این یک گاردِ ساختاری است نه احتیاط:
 * اقتصادِ استارز نردبانِ خودش را دارد (`STAR_LADDERS` + آزمایشِ `stars_price_v1`) و با
 * کلیدِ بسته کار می‌کند، پس یک `basic`ِ ۵ الماسی آن‌جا یعنی فاکتورِ استارز عددِ الماسِ
 * دروغ چاپ کند. */
const priceArm = (uid) => {
  if (starsRail) return 'control';
  try {
    const key = activePriceExperiment();
    if (!key) return 'control';
    const v = peekVariant(db, uid, key);
    return PRICE_LADDERS[v] ? v : 'control';
  } catch (e) { logErr('price arm:', e.message); return 'control'; }
};

/* ثبتِ exposure — **فقط بعد از اینکه پیامِ قیمت‌ها واقعاً به کاربر رسید**.
 * بند ۲و/۶د ریشه: «نمایشِ قیمت یعنی exposure». کاربری که قیمت‌ها را دید و منصرف شد هم
 * treatment را دیده، پس باید شمرده شود؛ و کاربری که پیامش اصلاً نرفت نباید شمرده شود،
 * وگرنه آزمایش با کسانی رقیق می‌شود که هیچ‌وقت چیزی ندیدند. برای همین مسیرِ رندر
 * `peekVariant` می‌خواند و این تابع **بعد از** ارسالِ موفق صدا زده می‌شود. */
const exposePrice = (uid) => {
  if (starsRail) return;
  try { const key = activePriceExperiment(); if (key) expose(db, uid, key); }
  catch (e) { logErr('price expose:', e.message); }
};

/* رنگِ CTA یک آزمایشِ مستقل است، اما «مستقل» به معنیِ رهاکردنِ توازنِ قیمت نیست.
 * stratum از همان بازویی ساخته می‌شود که کاربر در فروشگاه می‌بیند؛ بنابراین در هر
 * بازوی قیمت (فعلاً control/bulk) نیمی از کاربران plain و نیمی colored می‌مانند.
 * روی ریل Stars اصلاً آزمایشِ قیمتِ تومانی نداریم و یک لایه‌ی جدا می‌گیرند. */
const moneyCtaStratum = (uid) => {
  if (starsRail) return 'price:outside';
  const priceExperiment = activePriceExperiment();
  return priceExperiment ? `price:${priceExperiment}:${priceArm(uid)}` : 'price:none';
};
const moneyCtaVariant = (uid) => {
  if (!coinsOn(uid)) return 'control';
  return reserveStratifiedVariant(db, uid, MONEY_CTA_STYLE_EXPERIMENT, moneyCtaStratum(uid));
};
const moneyCtaIsColored = (uid) => moneyCtaVariant(uid) === MONEY_CTA_COLORED_VARIANT;
const exposeMoneyCtaStyle = (uid) => {
  if (!coinsOn(uid)) return 'control';
  return exposeStratifiedVariant(db, uid, MONEY_CTA_STYLE_EXPERIMENT, moneyCtaStratum(uid));
};
const releaseMoneyCtaStyle = (uid) => {
  if (coinsOn(uid)) releaseStratifiedReservation(db, uid, MONEY_CTA_STYLE_EXPERIMENT);
};
/* event جدا برای هر CTA: داشبورد می‌تواند بسته را متریک اصلی و خرید الماس را
 * گاردریل بگیرد، بدون اینکه کلیکِ یکی داخلِ دیگری حل شود. */
const trackMoneyCtaCallback = (uid, cta, packageKey = '') => {
  if (!coinsOn(uid)) return;
  const visual = moneyCtaVariant(uid);
  exposeMoneyCtaStyle(uid); // خودِ callback شاهدِ قویِ دیده‌شدنِ CTA است.
  track(db, uid, cta === 'package' ? 'money_package_callback' : 'money_recharge_callback', {
    variant: visual, package_key: packageKey,
  });
};

/* تنها منبعِ «چه بسته‌هایی در فروشگاه دیده می‌شوند» — حالا per کاربر، چون قیمت per بازو
 * است. هر جای رندر از همین می‌خواند، پس نه روشن/خاموش‌کردنِ `EXTRA_PACKS_ENABLED` مسیری
 * را جا می‌گذارد و نه آزمایشِ قیمت (همان الگوی helperِ بند ۲ج-۲). */
const shopPackages = (uid) => [
  ...(PRICE_LADDERS[priceArm(uid)] || COIN_PACKAGES),
  ...(EXTRA_PACKS_ENABLED ? EXTRA_PACKAGES : []),
];
/* بسته‌ای که **این کاربر** با این کلید می‌خرد. فالبک به `PACKAGE_BY_KEY` عمدی است و
 * فقط یک مصرف دارد: کلیدِ بازنشسته (`legend`/`eternal`) که در هیچ نردبانی نیست ولی
 * دکمه‌اش در چتِ کاربر زنده مانده و باید پیامِ مودبانه بگیرد نه سکوت (بند ۲ج/۶). */
const packForUser = (uid, key) =>
  shopPackages(uid).find(p => p.key === key) || PACKAGE_BY_KEY[key] || null;
// بسته‌ی یک پرداخت (null = پرداختِ غیربسته‌ای). تنها راهِ رسیدنِ نامِ بسته و تعدادِ الماس
// به پیام‌های ادمین؛ چون `payments.original_amount` برای بسته **واحدِ داخلی** است نه تومان
// و بدونِ این، ادمین عددِ بی‌معنی می‌بیند (باگِ رسیدِ #۱۵۳، ۱۴۰۵/۰۵/۳۰).
const packOf = (p) => (p && p.pkg ? PACKAGE_BY_KEY[p.pkg] || null : null);

/* ⭐ تبدیلِ تومان به استارز — فقط برای سوییچِ فارسی (بالا).
 *
 * ثابتِ تکی: هر استار = $۰.۰۱۸ (دلار/تتر، فرقی ندارد چون تتر به دلار قفل است).
 * محاسبه یک‌مرحله‌ای است، بدونِ نرخِ رسمی/مارک‌آپِ جداگانه.
 *
 * منبعِ نرخ: قیمتِ لحظه‌ایِ تتر روی نوبیتکس (`market/stats`, `srcCurrency=usdt,
 * dstCurrency=rls`) — API عمومی و بدونِ نیاز به کلید (سقفِ اعلام‌شده‌ی ۲۰
 * ریکوئست/دقیقه؛ با کشِ ۶ساعته‌ی زیر عملاً هرگز نزدیکش نمی‌شویم، شاید چند ده‌بار
 * در **روز** نه در دقیقه). ⚠️ **صادقانه (بند ۹/۰الف ریشه):** شکلِ دقیقِ پاسخ از
 * این محیطِ توسعه تأیید نشد — کلِ دامنه‌ی nobitex.ir را پراکسیِ این محیط با
 * policy denial رد می‌کند (نه فقط timeout؛ با curlِ مستقیم هم `403 connect_rejected`
 * گرفتم). پارسِ زیر عمداً مقاوم است (چند شکلِ محتملِ کلید را امتحان می‌کند) و کف/سقف
 * هر پاسخِ بدشکل را بی‌صدا رد می‌کند؛ fallbackِ ثابت همیشه امن است. بعد از اولین
 * دیپلوی از `Ops logs app=tarot` مطمئن شو fetch واقعاً جواب می‌گیرد. */
const USD_PER_STAR = 0.018;
const NOBITEX_STATS_URL = 'https://apiv2.nobitex.ir/market/stats?srcCurrency=usdt&dstCurrency=rls';
const FX_FALLBACK_TOMAN_PER_USDT = Number(process.env.USDT_TOMAN_RATE) || 220_000;
// کف/سقفِ معقول برای رد کردنِ پاسخِ بدشکل/خراب بدونِ اینکه فاکتور را با یک عددِ
// مهمل بسازد — همیشه ایمن‌تر از fallback است تا اینکه یک عددِ باطل را قبول کنیم.
const FX_SANITY_MIN = 50_000, FX_SANITY_MAX = 3_000_000;
const FX_CACHE_MS = 6 * 3600 * 1000; // ۶ ساعت — نرخِ بازار آن‌قدر سریع عوض نمی‌شود
let fxCache = { rate: 0, at: 0 };
async function fetchLiveUsdtToman() {
  try {
    const res = await fetch(NOBITEX_STATS_URL, { signal: AbortSignal.timeout(5000) });
    if (!res.ok) throw new Error(`http ${res.status}`);
    const data = await res.json();
    const stats = data?.stats;
    const stat = stats?.['usdt-rls'] || stats?.['usdtrls']
      || (stats && typeof stats === 'object'
        ? Object.entries(stats).find(([k]) => /usdt/i.test(k))?.[1] : null);
    const rial = Number(stat?.latest ?? stat?.last);
    if (!Number.isFinite(rial) || rial <= 0) throw new Error(`no usable price: ${rial}`);
    const toman = rial / 10; // نوبیتکس به ریال می‌دهد، ۱ تومان = ۱۰ ریال
    if (toman < FX_SANITY_MIN || toman > FX_SANITY_MAX) {
      throw new Error(`out of sanity range: ${toman}`);
    }
    return toman;
  } catch (e) { logErr('fx fetch:', e.message); return 0; }
}
async function usdtTomanRate() {
  const now = Date.now();
  if (fxCache.rate && now - fxCache.at < FX_CACHE_MS) return fxCache.rate;
  const live = await fetchLiveUsdtToman();
  if (live > 0) { fxCache = { rate: live, at: now }; return live; }
  return fxCache.rate || FX_FALLBACK_TOMAN_PER_USDT;
}
/** تومان ⟶ استارز، گردِ بالا. `usdtToman` را از پیش با `usdtTomanRate()` بگیر (async است). */
function starsForToman(amountToman, usdtToman) {
  const tomanPerStar = usdtToman * USD_PER_STAR;
  return Math.max(1, Math.ceil(amountToman / tomanPerStar));
}

const CARD_NUMBER = '6219861904145405';
const CARD_OWNER  = 'علیرضا اولیا — بلوبانک';
const CARD_RECIPIENT_NAME = 'علیرضا اولیا';   // نامِ گیرنده (تطبیق در ایجنتِ رسید)
const CARD_DEST_LAST4     = '5405';            // چهار رقمِ آخرِ کارتِ مقصد (تطبیق در ایجنتِ رسید)

// ایجنتِ رسیدِ کارت‌به‌کارت (Gemini Flash از طریق OpenRouter): auto-approve با شبکه‌ی ایمنیِ
// برگشت + بی‌اعتمادی. کلیدِ خاموشیِ سراسری (env RECEIPT_AI_AUTO_APPROVE=false → همه‌ی رسیدها
// دستی به ادمین می‌روند، بدون تصمیمِ خودکار). پیش‌فرض: روشن.
const RECEIPT_AI_AUTO_APPROVE = (process.env.RECEIPT_AI_AUTO_APPROVE ?? 'true').toLowerCase() !== 'false';
const RECEIPT_MODEL = FLASH;
// دکمه‌ی کپیِ شماره کارت (Telegram copy_text — کلیک = کپی به کلیپ‌بورد). قاعده‌ی سراسری:
// هر پیامِ پرداختِ کارت‌به‌کارت که شماره کارت را نشان می‌دهد باید این دکمه را زیرش داشته باشد.
const cardCopyRow = () => [{ text: '📋 کپی شماره کارت', copy_text: { text: CARD_NUMBER } }];
// دکمه‌ی سوییچ به استارز، درست زیرِ دکمه‌ی کپیِ کارت (خواسته‌ی صریحِ مالک). آرایه‌ی
// **ردیف‌ها** برمی‌گرداند (مثلِ الگوی `navMenuRow`) تا هر محلِ صدور با
// `...starsToggleRow(uid, paymentId, hasPkg)` بی‌قید و شرط اسپرد کند.
// ⚠️ `hasPkg` اجباری است: `buildInvoice` (starspay.js) بدونِ `pack.key` خطا می‌دهد، و
// فاکتورِ بدونِ بسته (دنیای تومانیِ میراثی) اصلاً چیزی برای تبدیل به استارز ندارد — پس
// دکمه فقط برای فاکتورِ **بسته‌ای** نشان داده می‌شود، نه هر فاکتوری.
const starsToggleRow = (uid, paymentId, hasPkg) =>
  (hasPkg && starsToggleOn(uid)) ? [[Markup.button.callback(L.buttons.payWithStars, `stars_toggle:${paymentId}`)]] : [];

// 🎁 هدیه‌ی خوش‌آمد (v2.0.0): دقیقاً بهای یک فالِ کاملِ سه‌کارتی، تا کاربرِ جدید **قبل از
// هر پی‌والی** ارزشِ واقعیِ محصول را ببیند (بند ۱۰ ریشه: اول ارزش، بعد پول). write-once با
// ستونِ users.welcome_bonus_at — ری‌استارت/چندبار /start دوباره هدیه نمی‌دهد.
const WELCOME_BONUS    = 30_000;
const QUICK_AMOUNTS    = [50_000, 100_000, 200_000];
const MIN_RECHARGE     = 10_000;  // کف‌گیرِ اشتباهِ تایپی (پایین‌تر از ارزان‌ترین فال)

/* ♻️ عمرِ ردیفِ پرداخت — دو عدد با دو معنیِ کاملاً متفاوت.
 *
 * `PAY_ROW_REUSE_SEC`: تا این مدت، تپِ دوباره‌ی «خرید الماس» **همان** ردیف را ادامه
 * می‌دهد و ردیفِ نو نمی‌سازد. تا امروز هر تپ یک `INSERT` بود، پس کاربری که منو را باز
 * می‌کرد و برمی‌گشت، پشتِ سرش ردیف‌های `pending/amount` با `amount=0` جا می‌گذاشت که
 * هیچ مسیری دیگر سراغشان نمی‌رفت. روی دیتای زنده اندازه‌گیری شد: از ۲۵۱ ردیفِ پرداخت،
 * ۲۵ تا دقیقاً همین بودند (هر ۲۵ تا `amount=0`).
 *
 * `RECEIPT_RECOVERY_SEC`: پنجره‌ای که رسیدِ بی‌استیت (کاربر بعد از فاکتور /start زده)
 * هنوز به فاکتورش وصل می‌شود. **تک‌منبع است** و هم مسیرِ بازیابیِ رسید از آن می‌خواند
 * هم جاروی ردیف‌های مرده. اگر دو عددِ جدا بودند، پهن‌کردنِ پنجره‌ی بازیابی بی‌صدا باعث
 * می‌شد جارو ردیف‌هایی را بکشد که هنوز قابلِ استفاده‌اند، یعنی پولِ واریزشده‌ی کاربر در
 * سیاه‌چاله بیفتد. همین جفت‌بودن است که جارو را اثباتاً بی‌خطر می‌کند: چیزی که جارو
 * می‌بندد، آن کوئری از قبل پیدایش نمی‌کند. */
const PAY_ROW_REUSE_SEC    = 15 * 60;
const RECEIPT_RECOVERY_SEC = 3 * 24 * 3600;
// پنجره‌ی کوتاه‌ترِ احیای فاکتورِ لغوشده (لغو گاهی عمدی است؛ رسیدِ همان روز عمدی نیست)
const CANCELED_RECOVERY_SEC = 12 * 3600;
/* ⏱ چرخه‌ی عمرِ فاکتور — v3.74.0، خواستهٔ صریحِ مالک («۱ ساعت یادآوری، ۲۴ ساعت انقضا»).
 * فقط برای ریلِ کارت (`!starsRail`) فعال است: فاکتورِ استارزِ کارت‌به‌کارت اصلاً وجود
 * ندارد، خودِ تلگرام پرداخت را همان لحظه تأیید/رد می‌کند و بند بالای `starspay.js` صریح
 * می‌گوید «رسید در این ریل معنا ندارد» — پس چیزی برای یادآوری/ادیت نیست.
 * ⚠️ این با `sweepDeadPaymentRows`/`RECEIPT_RECOVERY_SEC` (۷۲ ساعت، بالاتر) **جایگزین
 * نمی‌شود، رویش می‌نشیند**: آن یکی همچنان به‌عنوان بک‌استاپِ عمیق برای هر ردیفی که
 * به‌هر‌دلیل از این چرخه جا مانده (مثلاً `invoice_issued_at` قدیمی‌تر از این نسخه، که
 * NULL می‌ماند و اصلاً کاندیدِ این کوئری‌ها نیست) دست‌نخورده باقی می‌ماند. سقفِ ۲۴ ساعتِ
 * این‌جا همیشه زودتر از بک‌استاپِ ۷۲ ساعته می‌رسد، پس در عمل بک‌استاپ دیگر برای فاکتورهای
 * تازه اجرا نمی‌شود — ولی حذفش نشد چون هنوز شبکه‌ی ایمنیِ ردیف‌های قدیمی‌تر است.
 * انقضا وضعیت را به همان `canceled`ِ همیشگی می‌برد، نه یک وضعیتِ تازه: یعنی رسیدی که
 * دیر برسد از همان مسیرِ اثبات‌شده‌ی `CANCELED_RECOVERY_SEC` (بالا) خودکار احیا می‌شود —
 * بدونِ این، رسیدِ دیرِ کاربر بعد از انقضا بی‌صدا دور ریخته می‌شد (بند ۹ب/۹ ریشه). */
const INVOICE_REMINDER_SEC = 3600;      // ۱ ساعت
