  latestOpenReading: db.prepare(`
    SELECT id, status, price FROM readings
     WHERE user_id=? AND status IN ('pending_payment','paid','started')
     ORDER BY id DESC LIMIT 1`),
  // 🌙 مخاطبِ یادآوریِ شبانه (A/B). عمداً از **همان** ستون‌های یادآوریِ قدیمیِ کارتِ روز
  // می‌خواند (`daily_reminder_off` و `last_daily_reminder_at`) و ستونِ تازه نمی‌سازد:
  // کسی که قبلاً گفته «دیگه یادآوری نکن» باید همچنان خاموش بماند. برگرداندنِ یادآوری
  // نباید opt-outِ کاربر را بی‌اثر کند.
  // شرطِ «امروز هنوز کاری نکرده» عمداً این‌جا نیست: هر شاخه‌ی A/B شرطِ **خودش** را دارد
  // (A: کارتِ روز، B: کارتِ شانس) و در خودِ جارو چک می‌شود، وگرنه کوئری باید هر دو را
  // با OR می‌گرفت و کاربرِ شاخه‌ی اشتباه هم بی‌دلیل بیدار می‌شد.
  // ⚠️ `state`/`last_seen_at`/`created_at` از v3.56.0 برداشته می‌شوند تا جارو بتواند
  // «وسطِ فلوی زنده» و «روزِ اولِ کاربر» را رد کند. خودِ شرطِ SQL عوض نشد؛ فیلترِ تازه
  // در JS است چون مرزِ روز **منطقه‌ی زمانیِ هر زبان** را می‌خواهد (`botToday`) و SQLite
  // آن را نمی‌داند.
  dueNightReminder: db.prepare(`
    SELECT telegram_id, last_daily_date, lucky_date, state, last_seen_at, created_at FROM users
     WHERE welcomed=1 AND daily_reminder_off=0
       AND (last_daily_reminder_at IS NULL OR last_daily_reminder_at < unixepoch()-64800)
     LIMIT 400`),
  // 🌙 همان کوئری، ولی برای **بعد از پایانِ آزمایش** که دو یادآوری مستقل می‌شوند و کاربر
  // می‌تواند فقط کارتِ شانس را روشن نگه دارد. عمداً یک statement جداست و بالایی
  // دست‌نخورده ماند: تا وقتی آزمایش running است باید رفتار بیت‌به‌بیت همان امروز بماند.
  dueNightReminderFree: db.prepare(`
    SELECT telegram_id, last_daily_date, lucky_date, daily_reminder_off, lucky_reminder_on,
           state, last_seen_at, created_at FROM users
     WHERE welcomed=1 AND (daily_reminder_off=0 OR lucky_reminder_on=1)
       AND (last_daily_reminder_at IS NULL OR last_daily_reminder_at < unixepoch()-64800)
     LIMIT 400`),
  // 🎲 شبِ اولِ کارتِ شانس (بند ۲ج/۴: گفتگو همیشه مقدم است، v3.91.0). با حذفِ تبلیغِ
  // روزانه‌ی کارتِ شانس بعد از اولین فال (بالا)، تنها لحظه‌ای که کاربرِ تازه با آن آشنا
  // می‌شود همین یادآوریِ شبِ اول است. عمداً از `dueNightReminder`/`dueNightReminderFree`
  // جدا است: آن دو `daily_reminder_off=0` می‌خواهند و کاربرِ تازه با دیفالتِ
  // `daily_reminder_off=1, lucky_reminder_on=1` وارد آن مجموعه نمی‌شود.
  dueFirstNightLucky: db.prepare(`
    SELECT telegram_id, display_name, lucky_date, created_at, state, last_seen_at FROM users
     WHERE welcomed=1 AND created_at > unixepoch()-172800
       AND (last_daily_reminder_at IS NULL OR last_daily_reminder_at < unixepoch()-64800)
     LIMIT 400`),
  // 🍀 کارت شانس. `claimLucky` گاردِ اتمیکِ «روزی یک بار» است: شرطِ روز داخلِ خودِ UPDATE
  // نشسته، پس دو تپِ هم‌زمان فقط یک بار changes=1 می‌دهد (همان الگوی claimWelcomeBonus).
  claimLucky: db.prepare("UPDATE users SET lucky_date=? WHERE telegram_id=? AND COALESCE(lucky_date,'') <> ?"),
  setLuckyReminder: db.prepare('UPDATE users SET lucky_reminder_on=? WHERE telegram_id=?'),
  setLuckyHand: db.prepare('UPDATE users SET lucky_hand=? WHERE telegram_id=?'),
  bumpLuckyHands: db.prepare('UPDATE users SET lucky_hands = lucky_hands + 1 WHERE telegram_id=?'),
  // ⚠️ `setLuckyReminded`/`dueLuckyReminder` با آمدنِ یادآوریِ شبانه‌ی A/B حذف شدند (کدِ
  // مرده، بند ۹/۰ ریشه). ستون‌های `lucky_reminder_on` و `last_lucky_reminder_at` طبق بند
  // ۲ج/۱ روی دیتابیس می‌مانند و دکمه‌ی `lremind:` هم زنده است.
  // اصلاحِ فاکتور به مبلغِ واقعاً پرداخت‌شده (پرداختِ کمتر). original_amount هم برابر می‌شود
  // تا اعتبارِ approvePayment دقیقاً همان چیزی باشد که کاربر داده، نه بیشتر.
  adjustPaymentAmount: db.prepare(
    "UPDATE payments SET amount=?, original_amount=?, adjust_note=?, updated_at=unixepoch() WHERE id=? AND status IN ('pending','waiting_review')"),
  // بسته‌ی الماس: original_amount را claimAmount گذاشته (ارزشِ الماس‌ها)، این‌جا فقط مبلغِ
  // پرداختیِ واقعی و کلیدِ بسته می‌نشیند. گاردِ step='receipt' یعنی بعد از نهایی‌شدنِ
  // فاکتور دیگر بسته عوض نمی‌شود.
  // دقیقاً هم‌شکلِ setPaymentDiscount: `original_amount` اعتباری است که داده می‌شود (ارزشِ
